def _call_claude_proxy(prompt: str, system: str, max_tokens: int, model: str = "claude-sonnet-4-6", timeout: int = 90) -> str:
    """Call local Claude proxy server (for Streamlit Cloud — uses CLI on Tyler's machine)."""
    import urllib.request, urllib.error
    proxy_url = _get_proxy_url()
    if not proxy_url:
        raise Exception("No proxy configured")
    body = json.dumps({"prompt": prompt, "system": system, "max_tokens": max_tokens, "model": model}).encode()
    key_candidates = _proxy_key_candidates() or [""]
    last_error = ""
    for proxy_key in key_candidates:
        headers = {"Content-Type": "application/json", "ngrok-skip-browser-warning": "1"}
        if proxy_key:
            headers["X-Proxy-Key"] = proxy_key
        req = urllib.request.Request(f"{proxy_url.rstrip('/')}/call", data=body, headers=headers, method="POST")
        try:
            with urllib.request.urlopen(req, timeout=timeout) as resp:
                data = json.loads(resp.read())
            break
        except urllib.error.HTTPError as exc:
            raw_error = exc.read().decode("utf-8", errors="ignore")
            try:
                payload = json.loads(raw_error)
            except Exception:
                payload = None
            last_error = (payload or {}).get("error") or raw_error or f"Proxy request failed with HTTP {exc.code}"
            if exc.code == 403 and proxy_key != key_candidates[-1]:
                continue
            raise Exception(last_error)
    else:
        raise Exception(last_error or "Proxy request failed")
    if "error" in data:
        raise Exception(data["error"])
    return data["text"]


def _proxy_json_request(path: str, payload: dict | None = None, *, method: str = "POST", timeout: int = 90) -> dict:
    import urllib.request, urllib.error
    proxy_url = _get_proxy_url()
    if not proxy_url:
        raise Exception("No proxy configured")
    body = None
    if method.upper() != "GET":
        body = json.dumps(payload or {}).encode()
    key_candidates = _proxy_key_candidates() or [""]
    last_error = ""
    for proxy_key in key_candidates:
        headers = {"Content-Type": "application/json", "ngrok-skip-browser-warning": "1"}
        if proxy_key:
            headers["X-Proxy-Key"] = proxy_key
        req = urllib.request.Request(f"{proxy_url.rstrip('/')}{path}", data=body, headers=headers, method=method.upper())
        try:
            with urllib.request.urlopen(req, timeout=timeout) as resp:
                data = json.loads(resp.read())
            break
        except urllib.error.HTTPError as exc:
            raw_error = exc.read().decode("utf-8", errors="ignore")
            try:
                error_payload = json.loads(raw_error)
            except Exception:
                error_payload = None
            last_error = (error_payload or {}).get("error") or raw_error or f"Proxy request failed with HTTP {exc.code}"
            if exc.code == 403 and proxy_key != key_candidates[-1]:
                continue
            raise Exception(last_error)
    else:
        raise Exception(last_error or "Proxy request failed")
    if data.get("error"):
        raise Exception(data["error"])
    return data


def _proxy_binary_request(path: str, *, timeout: int = 90) -> tuple[bytes, str]:
    import urllib.request, urllib.error
    proxy_url = _get_proxy_url()
    if not proxy_url:
        raise Exception("No proxy configured")
    key_candidates = _proxy_key_candidates() or [""]
    last_error = ""
    for proxy_key in key_candidates:
        headers = {"ngrok-skip-browser-warning": "1"}
        if proxy_key:
            headers["X-Proxy-Key"] = proxy_key
        req = urllib.request.Request(f"{proxy_url.rstrip('/')}{path}", headers=headers, method="GET")
        try:
            with urllib.request.urlopen(req, timeout=timeout) as resp:
                return resp.read(), resp.headers.get_content_type() or "application/octet-stream"
        except urllib.error.HTTPError as exc:
            raw_error = exc.read().decode("utf-8", errors="ignore")
            last_error = raw_error or f"Proxy request failed with HTTP {exc.code}"
            if exc.code == 403 and proxy_key != key_candidates[-1]:
                continue
            raise Exception(last_error)
    raise Exception(last_error or "Proxy request failed")


