def _call_claude_inspiration(prompt: str, system: str, max_tokens: int = 1000, model: str = "claude-sonnet-4-6") -> str:
    """
    What's Hot should stay Anthropic-first but fail fast.

    Use the direct Anthropic route first, then a short proxy retry, then let the
    deterministic feed fallback take over instead of walking the full long AI
    router chain.
    """
    _inspo_timeout = 45
    try:
        return _call_claude_direct(prompt, system or "", max_tokens, model, timeout=_inspo_timeout)
    except Exception:
        pass
    try:
        return _call_claude_proxy(prompt, system or "", max_tokens, model, timeout=_inspo_timeout)
    except Exception:
        return ""


def _call_claude_grades(prompt: str, system: str, max_tokens: int = 700, model: str = "claude-sonnet-4-6") -> str:
    """
    Grades must be reliable.

    Do not use the general Streamlit-aware router from worker threads because
    it touches session state. Use only thread-safe direct/proxy calls here.
    """
    tok = _get_oauth_token() or _get_access_token()
    if tok:
        try:
            return _call_claude_direct(prompt, system, max_tokens, model, _token=tok, timeout=15)
        except Exception:
            pass
    try:
        return _call_claude_proxy(prompt, system, max_tokens, model, timeout=15)
    except Exception:
        return ""


def _post_tweet(text: str) -> tuple[bool, str]:
    """Post a new tweet natively first, then proxy/local helper, or return X composer fallback."""
    clean_text = (text or "").strip()[:280]
    if not clean_text:
        return False, "No tweet text to post"
    intent_url = _x_intent_url(clean_text)
    native_ok, native_detail = _post_tweet_native_x(clean_text)
    if native_ok:
        return True, native_detail

    helper_error = ""
    helper_ok, helper_detail = _post_tweet_xurl_helper(clean_text)
    if helper_ok:
        return True, helper_detail
    helper_error = helper_detail

    proxy_error = ""
    proxy_url = _get_proxy_url()
    if proxy_url:
        try:
            data = _proxy_json_request("/tweet/post", {"text": clean_text}, method="POST", timeout=30)
            if data.get("ok", False):
                detail = data.get("tweet_url") or data.get("screen_name") or ""
                return True, detail
            proxy_error = data.get("error", "Proxy returned not ok")
        except Exception as e:
            proxy_error = f"Proxy error: {e}"
    failure_parts = [f"Native X: {native_detail}"]
    if helper_error:
        failure_parts.append(f"Local X helper: {helper_error}")
    if proxy_error:
        failure_parts.append(f"Proxy: {proxy_error}")
    if not proxy_url:
        failure_parts.append("Proxy: not configured")
    return False, f"Open in X to post: {intent_url}\n\nDirect post failed. " + " | ".join(failure_parts)


def _xurl_helper_app_name() -> str:
    configured = _secret_or_env("XURL_APP_NAME", "X_POST_APP_NAME", "TWITTER_XURL_APP_NAME").strip()
    return configured or "my-app"


def _post_tweet_xurl_helper(text: str) -> tuple[bool, str]:
    helper = "/home/polfam/.openclaw/scripts/twitter_post.py"
    if not os.path.exists(helper):
        return False, "local tweet helper not found"
    app_name = _xurl_helper_app_name()
    try:
        result = subprocess.run(
            ["python3", helper, "--app-name", app_name, "--text", text],
            capture_output=True,
            text=True,
            timeout=180,
        )
    except subprocess.TimeoutExpired:
        return False, f"timed out using xurl profile {app_name}"
    except Exception as exc:
        return False, str(exc)[:240]
    stdout = (result.stdout or "").strip()
    stderr = (result.stderr or "").strip()
    if result.returncode != 0:
        return False, stderr or stdout or f"xurl profile {app_name} failed"
    try:
        payload = json.loads(stdout)
    except Exception:
        payload = {}
    if isinstance(payload, dict) and not payload.get("ok", True):
        return False, str(payload.get("error") or stdout)[:300]
    tweet_id = str((payload or {}).get("tweet_id") or "")
    if tweet_id:
        handle = get_current_handle()
        if handle:
            return True, f"https://x.com/{handle.lstrip('@')}/status/{tweet_id}"
        return True, tweet_id
    return True, ""


def _x_intent_url(text: str) -> str:
    import urllib.parse as _up

    return "https://twitter.com/intent/tweet?text=" + _up.quote((text or "").strip()[:280])


def _x_native_post_credentials() -> dict:
    return {
        "consumer_key": _secret_or_env("X_API_KEY", "TWITTER_API_KEY", "X_CONSUMER_KEY", "TWITTER_CONSUMER_KEY"),
        "consumer_secret": _secret_or_env("X_API_SECRET", "TWITTER_API_SECRET", "X_CONSUMER_SECRET", "TWITTER_CONSUMER_SECRET", "TWITTER_API_KEY_SECRET"),
        "access_token": _secret_or_env("X_ACCESS_TOKEN", "TWITTER_ACCESS_TOKEN"),
        "access_secret": _secret_or_env("X_ACCESS_TOKEN_SECRET", "TWITTER_ACCESS_TOKEN_SECRET"),
        "username": _secret_or_env("X_USERNAME", "TWITTER_USERNAME", "X_SCREEN_NAME", "TWITTER_SCREEN_NAME").lstrip("@"),
    }


def _x_oauth_percent(value: object) -> str:
    import urllib.parse as _up

    return _up.quote(str(value), safe="~-._")


def _x_oauth1_header(method: str, url: str, creds: dict, extra_params: dict | None = None) -> str:
    import base64
    import hmac
    import secrets as _secrets
    import urllib.parse as _up

    oauth_params = {
        "oauth_consumer_key": creds["consumer_key"],
        "oauth_nonce": _secrets.token_hex(16),
        "oauth_signature_method": "HMAC-SHA1",
        "oauth_timestamp": str(int(time.time())),
        "oauth_token": creds["access_token"],
        "oauth_version": "1.0",
    }
    signing_params = dict(oauth_params)
    signing_params.update(extra_params or {})
    parsed = _up.urlparse(url)
    base_url = f"{parsed.scheme}://{parsed.netloc}{parsed.path}"
    normalized = "&".join(
        f"{_x_oauth_percent(k)}={_x_oauth_percent(v)}"
        for k, v in sorted(signing_params.items())
    )
    signature_base = "&".join([
        method.upper(),
        _x_oauth_percent(base_url),
        _x_oauth_percent(normalized),
    ])
    signing_key = f"{_x_oauth_percent(creds['consumer_secret'])}&{_x_oauth_percent(creds['access_secret'])}"
    digest = hmac.new(signing_key.encode(), signature_base.encode(), hashlib.sha1).digest()
    oauth_params["oauth_signature"] = base64.b64encode(digest).decode()
    return "OAuth " + ", ".join(
        f'{_x_oauth_percent(k)}="{_x_oauth_percent(v)}"'
        for k, v in sorted(oauth_params.items())
    )


def _post_tweet_native_x(text: str) -> tuple[bool, str]:
    """Post through X API v2. Requires OAuth 1.0a user-context app secrets."""
    import urllib.request

    creds = _x_native_post_credentials()
    missing = [name for name in ("consumer_key", "consumer_secret", "access_token", "access_secret") if not creds.get(name)]
    if missing:
        return False, "missing native X secrets: " + ", ".join(missing)
    url = "https://api.x.com/2/tweets"
    body = json.dumps({"text": text}).encode()
    req = urllib.request.Request(
        url,
        data=body,
        headers={
            "Authorization": _x_oauth1_header("POST", url, creds),
            "Content-Type": "application/json",
            "Accept": "application/json",
        },
        method="POST",
    )
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            data = json.loads(resp.read())
    except urllib.error.HTTPError as exc:
        raw = exc.read().decode("utf-8", errors="ignore")[:300]
        return False, f"HTTP {exc.code}: {raw}"
    except Exception as exc:
        return False, str(exc)[:300]
    tweet_id = str(((data or {}).get("data") or {}).get("id") or "")
    if not tweet_id:
        return False, f"native X response missing tweet id: {str(data)[:240]}"
    username = creds.get("username") or get_current_handle()
    if username:
        return True, f"https://x.com/{username.lstrip('@')}/status/{tweet_id}"
    return True, tweet_id


def _render_post_failure(detail: str, *, prefix: str = "Post failed") -> None:
    detail = str(detail or "").strip()
    match = re.search(r"https://twitter\.com/intent/tweet\?text=\S+", detail)
    if match:
        url = match.group(0)
        clean_detail = detail.replace(url, "").replace("Open in X to post:", "").strip()
        st.warning(f"{prefix}. Direct posting is unavailable right now, so use the X composer fallback.")
        st.markdown(
            f'<a href="{html.escape(url)}" target="_blank" '
            'style="display:inline-block;padding:9px 16px;background:#2DD4BF;border-radius:9px;'
            'color:#050810;font-weight:700;text-decoration:none;">Open in X to Post</a>',
            unsafe_allow_html=True,
        )
        if clean_detail:
            st.caption(clean_detail)
        return
    st.error(f"{prefix}: {detail}")


def _proxy_tweet_action(action: str, tweet_id: str, text: str = "") -> bool:
    """Route like/reply through local proxy. Returns True on success."""
    proxy_url = _get_proxy_url()
    try:
        data = _proxy_json_request(f"/tweet/{action}", {"tweet_id": tweet_id, "text": text}, method="POST", timeout=30)
        return data.get("ok", False)
    except Exception:
        # Fall back to the shared local helper for replies if available.
        helper = "/home/polfam/.openclaw/scripts/twitter_post.py"
        if action == "reply" and os.path.exists(helper):
            cmd = ["python3", helper, "--app-name", _xurl_helper_app_name(), "--text", text, "--reply-to", tweet_id]
            result = subprocess.run(cmd, capture_output=True, text=True, timeout=15)
            return result.returncode == 0
        return False


def _ai_failure_chain_start():
    st.session_state["_ai_error_chain"] = []
    st.session_state["_ai_last_error"] = ""


def _record_ai_failure(route: str, error: object) -> None:
    detail = f"{route} {str(error).strip()}"
    st.session_state["_ai_last_error"] = detail
    chain = st.session_state.setdefault("_ai_error_chain", [])
    chain.append(detail[:500])


def call_claude(prompt: str, system: str = None, max_tokens: int = 1500, model: str = "claude-sonnet-4-6",
                timeout_seconds: int | None = None) -> str:
    if system is None:
        system = get_voice_context()

    st.session_state["_ai_last_model"] = model
    _ai_failure_chain_start()
    hosted = _running_on_streamlit_cloud()
    api_key_routes_enabled = _streamlit_api_key_routes_enabled()

    # 0. Optional Streamlit API-key route. Disabled by default: website uses API keys;
    # root Streamlit uses OAuth/proxy/Codex OAuth unless explicitly opted in.
    if api_key_routes_enabled:
        try:
            result = _call_anthropic_api_key(prompt, system or "", max_tokens, model, timeout=timeout_seconds or 45)
            st.session_state["_ai_last_route"] = "anthropic_api_key"
            st.session_state["_ai_last_provider"] = "anthropic"
            st.session_state["_ai_last_source"] = "streamlit_api_key"
            st.session_state["_ai_last_at"] = datetime.now().isoformat(timespec="seconds")
            _append_debug_event("ai_call", "ok", "anthropic_api_key", {"model": model})
            return result
        except urllib.error.HTTPError as e:
            _record_ai_failure("anthropic_api_key", f"HTTP {e.code}: {e.read().decode('utf-8', errors='ignore')[:240]}")
            _append_debug_event("ai_call", "error", f"anthropic_api_key HTTP {e.code}", {"model": model})
        except Exception as e:
            _record_ai_failure("anthropic_api_key", e)
            _append_debug_event("ai_call", "error", f"anthropic_api_key {e}", {"model": model})

    # 1. Direct OAuth HTTP — fastest, no subprocess overhead
    if not hosted and not anthropic_is_blocked():
        try:
            result = _call_claude_direct(prompt, system or "", max_tokens, model, timeout=timeout_seconds or 30)
            anthropic_mark_available("streamlit_direct")
            st.session_state["_ai_last_route"] = "anthropic_direct"
            st.session_state["_ai_last_provider"] = "anthropic"
            st.session_state["_ai_last_source"] = "streamlit_direct"
            st.session_state["_ai_last_at"] = datetime.now().isoformat(timespec="seconds")
            _append_debug_event("ai_call", "ok", "anthropic_direct", {"model": model})
            return result
        except urllib.error.HTTPError as e:
            if e.code == 429:
                anthropic_mark_rate_limited(
                    anthropic_parse_retry_after(getattr(e, "headers", None)),
                    source="streamlit_direct",
                    error=f"HTTP {e.code}",
                )
                _record_ai_failure("anthropic_direct", f"HTTP {e.code}")
                _append_debug_event("ai_call", "error", f"anthropic_direct HTTP {e.code}", {"model": model})
        except Exception as e:
            if "Credit balance is too low" in str(e):
                anthropic_block_for(DEFAULT_UNAVAILABLE_COOLDOWN, source="streamlit_direct", error=str(e))
            _record_ai_failure("anthropic_direct", e)
            _append_debug_event("ai_call", "error", f"anthropic_direct {e}", {"model": model})

    # 2. Local CLI fallback
    if not hosted and os.path.exists(CLAUDE_CLI):
        try:
            clean_env = {k: v for k, v in os.environ.items() if k != "ANTHROPIC_API_KEY"}
            cmd = [CLAUDE_CLI, "-p", "--model", model]
            if system:
                cmd += ["--system-prompt", system]
            result = subprocess.run(
                cmd,
                input=prompt, capture_output=True, text=True, timeout=min(timeout_seconds or 20, 20), env=clean_env,
            )
            if result.returncode == 0 and result.stdout.strip():
                anthropic_mark_available("streamlit_cli")
                st.session_state["_ai_last_route"] = "anthropic_cli"
                st.session_state["_ai_last_provider"] = "anthropic"
                st.session_state["_ai_last_source"] = "streamlit_cli"
                st.session_state["_ai_last_at"] = datetime.now().isoformat(timespec="seconds")
                _append_debug_event("ai_call", "ok", "anthropic_cli", {"model": model})
                return result.stdout.strip()
            if "Credit balance is too low" in (result.stderr or ""):
                anthropic_block_for(DEFAULT_UNAVAILABLE_COOLDOWN, source="streamlit_cli", error=result.stderr.strip())
            if result.stderr:
                _record_ai_failure("anthropic_cli", result.stderr.strip())
                _append_debug_event("ai_call", "error", f"anthropic_cli {result.stderr.strip()}", {"model": model})
        except Exception as e:
            _record_ai_failure("anthropic_cli", e)

    # 3. Proxy server (Streamlit Cloud path — ngrok to Tyler's local machine)
    try:
        proxy_text = _call_claude_proxy(prompt, system or "", max_tokens, model, timeout=timeout_seconds or 90)
        st.session_state["_ai_last_route"] = "proxy"
        st.session_state["_ai_last_provider"] = "proxy"
        st.session_state["_ai_last_source"] = "streamlit_proxy"
        st.session_state["_ai_last_at"] = datetime.now().isoformat(timespec="seconds")
        _append_debug_event("ai_call", "ok", "proxy", {"model": model})
        return proxy_text
    except Exception as e:
        _record_ai_failure("proxy", e)
        _append_debug_event("ai_call", "error", f"proxy {e}", {"model": model})
        pass

    # 4. Optional OpenAI API-key fallback. Keep it out of the default Streamlit app
    # route so website API-key configuration cannot break app OAuth behavior.
    if api_key_routes_enabled:
        try:
            openai_text = _call_openai_api_key(prompt, system or "", max_tokens, timeout=timeout_seconds or 45)
            st.session_state["_ai_last_route"] = "openai_api_key"
            st.session_state["_ai_last_provider"] = "openai"
            st.session_state["_ai_last_source"] = "streamlit_api_key"
            st.session_state["_ai_last_at"] = datetime.now().isoformat(timespec="seconds")
            _append_debug_event("ai_call", "ok", "openai_api_key", {"model": _secret_or_env("OPENAI_MODEL") or "gpt-5.2"})
            return openai_text
        except urllib.error.HTTPError as e:
            _record_ai_failure("openai_api_key", f"HTTP {e.code}: {e.read().decode('utf-8', errors='ignore')[:240]}")
            _append_debug_event("ai_call", "error", f"openai_api_key HTTP {e.code}", {"model": _secret_or_env("OPENAI_MODEL") or "gpt-5.2"})
        except Exception as e:
            _record_ai_failure("openai_api_key", e)
            _append_debug_event("ai_call", "error", f"openai_api_key {e}", {"model": _secret_or_env("OPENAI_MODEL") or "gpt-5.2"})

    # 5. ChatGPT OAuth fallback via local Codex login. Local only; cloud has no Codex auth file.
    if not hosted:
        try:
            chatgpt_text = call_chatgpt_oauth(prompt, system or "")
            st.session_state["_ai_last_route"] = "chatgpt_oauth"
            st.session_state["_ai_last_provider"] = "chatgpt"
            st.session_state["_ai_last_source"] = "local_codex_oauth"
            st.session_state["_ai_last_at"] = datetime.now().isoformat(timespec="seconds")
            _append_debug_event("ai_call", "ok", "chatgpt_oauth", {"model": model})
            return chatgpt_text
        except Exception as e:
            _record_ai_failure("chatgpt_oauth", e)
            _append_debug_event("ai_call", "error", f"chatgpt_oauth {e}", {"model": model})
            pass

    return "AI unavailable — OAuth, proxy, and local Codex OAuth routes all failed."


def _is_ai_unavailable_text(value: str) -> bool:
    _text = str(value or "").strip().lower()
    if not _text:
        return False
    return (
        _text.startswith("ai unavailable")
        or _text.startswith("error: no oauth token")
        or "no proxy configured" in _text
    )


def _ci_capture_ai_error(raw_text: str) -> bool:
    if not _is_ai_unavailable_text(raw_text):
        return False
    _detail = str(st.session_state.get("_ai_last_error", "") or "").strip()
    _route = str(st.session_state.get("_ai_last_route", "") or "").strip()
    _source = str(st.session_state.get("_ai_last_source", "") or "").strip()
    _message = str(raw_text or "").strip()
    _chain = [str(item).strip() for item in st.session_state.get("_ai_error_chain", []) if str(item).strip()]
    if _detail:
        _message = f"{_message}\n\nLast failure: {_detail}"
    if _chain:
        _message += "\n\nRoute failures:\n" + "\n".join(f"- {item}" for item in _chain[-6:])
    if _route or _source:
        _message += f"\nRoute: {_route or 'unknown'}"
        if _source:
            _message += f" ({_source})"
    st.session_state["ci_error"] = _message
    for _k in ["ci_result", "ci_banger_data", "ci_repurposed", "ci_preview", "ci_grades"]:
        st.session_state.pop(_k, None)
    return True


def _gist_headers():
    pat = st.secrets.get("GITHUB_PAT", "") or os.environ.get("HQ_GITHUB_PAT", "")
    return {"Authorization": f"Bearer {pat}", "Accept": "application/vnd.github+json",
            "X-GitHub-Api-Version": "2022-11-28", "Content-Type": "application/json"}

def _load_bank_items(kind: str) -> list:
    if kind == "repurpose":
        local_name = "repurpose_queue.json"
        gist_name = "hq_repurpose.json"
    else:
        local_name = "inspiration_vault.json"
        gist_name = "hq_inspiration.json"
    if is_guest():
        return load_json(local_name, [])
    try:
        gist_id = st.secrets.get("GIST_ID", "15fb167bbbfdaa79d5ce11c266c3f652")
        resp = requests.get(f"https://api.github.com/gists/{gist_id}", headers=_gist_headers(), timeout=8)
        data = resp.json()
        if gist_name in data.get("files", {}):
            return json.loads(data["files"][gist_name]["content"])
    except Exception:
        pass
    return []


def _save_bank_items(kind: str, items: list):
    if kind == "repurpose":
        local_name = "repurpose_queue.json"
        gist_name = "hq_repurpose.json"
    else:
        local_name = "inspiration_vault.json"
        gist_name = "hq_inspiration.json"
    if is_guest():
        save_json(local_name, items)
        return
    try:
        gist_id = st.secrets.get("GIST_ID", "15fb167bbbfdaa79d5ce11c266c3f652")
        payload = json.dumps({"files": {gist_name: {"content": json.dumps(items, indent=2, default=str)}}})
        requests.patch(f"https://api.github.com/gists/{gist_id}", data=payload, headers=_gist_headers(), timeout=8)
    except Exception:
        pass


def load_inspiration_gist() -> list:
    return _load_bank_items("inspiration")

def save_inspiration_gist(items: list):
    _save_bank_items("inspiration", items)


def _load_actions_gist() -> dict:
    """Load liked/replied tweet IDs. Guests use local isolated storage; owner uses Gist."""
    _handle = get_current_handle()
    if st.session_state.get("_actions_cache_handle") == _handle and "_actions_cache" in st.session_state:
        return st.session_state["_actions_cache"]
    if is_guest():
        result = load_json("actions.json", {})
        result.setdefault("liked", [])
        result.setdefault("replied", [])
        st.session_state["_actions_cache"] = result
        st.session_state["_actions_cache_handle"] = _handle
        return result
    try:
        gist_id = st.secrets.get("GIST_ID", "15fb167bbbfdaa79d5ce11c266c3f652")
        resp = requests.get(f"https://api.github.com/gists/{gist_id}", headers=_gist_headers(), timeout=8)
        data = resp.json()
        content = data.get("files", {}).get("hq_actions.json", {}).get("content", "{}")
        result = json.loads(content)
    except Exception:
        result = {}
    result.setdefault("liked", [])
    result.setdefault("replied", [])
    st.session_state["_actions_cache"] = result
    st.session_state["_actions_cache_handle"] = _handle
    return result


def _save_actions_gist(actions: dict):
    """Persist liked/replied IDs. Guests use local isolated storage; owner uses Gist."""
    st.session_state["_actions_cache"] = actions
    st.session_state["_actions_cache_handle"] = get_current_handle()
    if is_guest():
        save_json("actions.json", actions)
        return
    try:
        gist_id = st.secrets.get("GIST_ID", "15fb167bbbfdaa79d5ce11c266c3f652")
        payload = json.dumps({"files": {"hq_actions.json": {"content": json.dumps(actions, indent=2)}}})
        requests.patch(f"https://api.github.com/gists/{gist_id}", data=payload, headers=_gist_headers(), timeout=5)
    except Exception:
        pass


def _podcast_store_filename() -> str:
    return podcast_store.LEGACY_STORE_FILENAME


def _podcast_store_cache_handle() -> str:
    role = "guest" if is_guest() else "owner"
    return f"{role}:{get_current_handle()}"


_PODCAST_OWNER_CACHE_TTL_SECONDS = 5.0


def _podcast_remote_cache_is_fresh(cache_handle: str) -> bool:
    if st.session_state.get("_podcast_runs_remote_cache_handle") != cache_handle:
        return False
    cached_at = float(st.session_state.get("_podcast_runs_remote_cache_loaded_at", 0) or 0)
    return (time.time() - cached_at) <= _PODCAST_OWNER_CACHE_TTL_SECONDS


def _load_podcast_local_store_raw() -> tuple[dict, str]:
    return podcast_store.load_local_store_raw(get_data_dir())


def _write_podcast_local_store(store: dict) -> None:
    podcast_store.write_local_store(store, get_data_dir())


def _load_podcast_remote_store_bundle_raw() -> tuple[dict, str, dict]:
    try:
        gist_id = st.secrets.get("GIST_ID", "15fb167bbbfdaa79d5ce11c266c3f652")
        resp = requests.get(f"https://api.github.com/gists/{gist_id}", headers=_gist_headers(), timeout=8)
        resp.raise_for_status()
        data = resp.json()
        files = data.get("files", {})

        def _fetch_text(raw_url: str) -> str:
            raw_resp = requests.get(raw_url, timeout=8)
            raw_resp.raise_for_status()
            return raw_resp.text

        return podcast_remote_store.load_remote_store_bundle_from_files(files, fetch_text=_fetch_text)
    except Exception as exc:
        return podcast_tracker.empty_podcast_store(), f"Gist read failed: {exc}", {
            "has_event_manifest": False,
            "event_batch_ids": [],
            "has_run_manifest": False,
        }


def _load_podcast_remote_store_raw() -> tuple[dict, str]:
    store, error, _remote_meta = _load_podcast_remote_store_bundle_raw()
    return store, error


def _load_podcast_runs_store() -> dict:
    cache_handle = _podcast_store_cache_handle()
    cached_store = st.session_state.get("_podcast_runs_cache")
    cached_at = float(st.session_state.get("_podcast_runs_cache_loaded_at", 0) or 0)
    cache_is_fresh = (time.time() - cached_at) <= _PODCAST_OWNER_CACHE_TTL_SECONDS
    if st.session_state.get("_podcast_runs_cache_handle") == cache_handle and cached_store is not None:
        if is_guest() or cache_is_fresh:
            return podcast_tracker.deepcopy_store(cached_store)

    local_store, local_error = _load_podcast_local_store_raw()
    load_source = "local"
    load_error = local_error
    if is_guest():
        store = local_store
    else:
        if _podcast_remote_cache_is_fresh(cache_handle):
            remote_store = podcast_tracker.deepcopy_store(st.session_state.get("_podcast_runs_remote_cache", podcast_tracker.empty_podcast_store()))
            remote_error = ""
        else:
            remote_store, remote_error, remote_meta = _load_podcast_remote_store_bundle_raw()
            if not remote_error:
                st.session_state["_podcast_runs_remote_cache"] = podcast_tracker.normalize_podcast_store(remote_store)
                st.session_state["_podcast_runs_remote_cache_handle"] = cache_handle
                st.session_state["_podcast_runs_remote_cache_loaded_at"] = time.time()
                st.session_state["_podcast_runs_remote_meta"] = remote_meta
        store = podcast_tracker.merge_podcast_stores(local_store, remote_store)
        if remote_error:
            load_source = "local_backup"
            load_error = remote_error if not local_error else f"{remote_error} | {local_error}"
        else:
            load_source = "gist"
            load_error = local_error
    normalized = podcast_tracker.normalize_podcast_store(store)
    st.session_state["_podcast_runs_cache"] = normalized
    st.session_state["_podcast_runs_cache_handle"] = cache_handle
    st.session_state["_podcast_runs_cache_loaded_at"] = time.time()
    st.session_state["_podcast_runs_persist_status"] = {"source": load_source, "error": load_error}
    return podcast_tracker.deepcopy_store(normalized)


def _save_podcast_runs_store(store: dict) -> dict:
    normalized = podcast_tracker.normalize_podcast_store(store)
    _write_podcast_local_store(normalized)
    if is_guest():
        st.session_state["_podcast_runs_cache"] = normalized
        st.session_state["_podcast_runs_cache_handle"] = _podcast_store_cache_handle()
        st.session_state["_podcast_runs_cache_loaded_at"] = time.time()
        st.session_state["_podcast_runs_persist_status"] = {"source": "local", "error": ""}
        return normalized

    cache_handle = _podcast_store_cache_handle()
    remote_store, remote_error, remote_meta = _load_podcast_remote_store_bundle_raw()
    if not remote_error:
        st.session_state["_podcast_runs_remote_cache"] = podcast_tracker.normalize_podcast_store(remote_store)
        st.session_state["_podcast_runs_remote_cache_handle"] = cache_handle
        st.session_state["_podcast_runs_remote_cache_loaded_at"] = time.time()
        st.session_state["_podcast_runs_remote_meta"] = remote_meta
    merged = podcast_tracker.merge_podcast_stores(normalized, remote_store)
    if remote_error:
        _write_podcast_local_store(merged)
        st.session_state["_podcast_runs_cache"] = merged
        st.session_state["_podcast_runs_cache_handle"] = cache_handle
        st.session_state["_podcast_runs_cache_loaded_at"] = time.time()
        st.session_state["_podcast_runs_remote_cache"] = podcast_tracker.empty_podcast_store()
        st.session_state["_podcast_runs_remote_cache_handle"] = cache_handle
        st.session_state["_podcast_runs_remote_cache_loaded_at"] = 0.0
        st.session_state["_podcast_runs_persist_status"] = {
            "source": "local_backup",
            "error": f"{remote_error}. Shared gist was not updated; local backup still saved.",
        }
        return merged
    try:
        gist_id = st.secrets.get("GIST_ID", "15fb167bbbfdaa79d5ce11c266c3f652")
        remote_previous = remote_store if not remote_error else podcast_tracker.empty_podcast_store()
        payload = json.dumps({
            "files": podcast_remote_store.build_remote_files_payload(
                merged,
                previous_store=remote_previous,
                previous_event_batch_ids=remote_meta.get("event_batch_ids", []),
                include_snapshot=False,
                force_all_runs=not remote_meta.get("has_run_manifest", False),
            )
        })
        resp = requests.patch(f"https://api.github.com/gists/{gist_id}", data=payload, headers=_gist_headers(), timeout=8)
        if 200 <= resp.status_code < 300:
            _write_podcast_local_store(merged)
            st.session_state["_podcast_runs_cache"] = merged
            st.session_state["_podcast_runs_cache_handle"] = cache_handle
            st.session_state["_podcast_runs_cache_loaded_at"] = time.time()
            st.session_state["_podcast_runs_remote_cache"] = merged
            st.session_state["_podcast_runs_remote_cache_handle"] = cache_handle
            st.session_state["_podcast_runs_remote_cache_loaded_at"] = time.time()
            st.session_state["_podcast_runs_persist_status"] = {
                "source": "gist",
                "error": remote_error,
            }
        else:
            _write_podcast_local_store(merged)
            st.session_state["_podcast_runs_cache"] = merged
            st.session_state["_podcast_runs_cache_handle"] = cache_handle
            st.session_state["_podcast_runs_cache_loaded_at"] = time.time()
            st.session_state["_podcast_runs_remote_cache"] = podcast_tracker.empty_podcast_store()
            st.session_state["_podcast_runs_remote_cache_handle"] = cache_handle
            st.session_state["_podcast_runs_remote_cache_loaded_at"] = 0.0
            st.session_state["_podcast_runs_persist_status"] = {
                "source": "local_backup",
                "error": f"Gist write failed with HTTP {resp.status_code}. Local backup still saved.",
            }
    except Exception as exc:
        _write_podcast_local_store(merged)
        st.session_state["_podcast_runs_cache"] = merged
        st.session_state["_podcast_runs_cache_handle"] = cache_handle
        st.session_state["_podcast_runs_cache_loaded_at"] = time.time()
        st.session_state["_podcast_runs_remote_cache"] = podcast_tracker.empty_podcast_store()
        st.session_state["_podcast_runs_remote_cache_handle"] = cache_handle
        st.session_state["_podcast_runs_remote_cache_loaded_at"] = 0.0
        st.session_state["_podcast_runs_persist_status"] = {
            "source": "local_backup",
            "error": f"Gist write failed: {exc}. Local backup still saved.",
        }
    return merged


def load_json(filename: str, default=None):
    path = get_data_dir() / filename
    if path.exists():
        try:
            return json.loads(path.read_text())
        except Exception:
            pass
    return default if default is not None else []


def save_json(filename: str, data):
    path = get_data_dir() / filename
    path.write_text(json.dumps(data, indent=2, default=str))


# Single source for every Streamlit surface that builds tweet copy with AI.
# Creator Studio owns the actual prompt formula; these helpers prevent What Hot,
# Signals, Reply Guy, Raw Thoughts, and future agents from drifting back to
# hard-coded "under X chars" or alternate default voice rules.
_FALLBACK_TWEET_FORMATS = ("Punchy Tweet", "Normal Tweet", "Long Tweet", "Thread", "Article")
_FALLBACK_TWEET_VOICES = ("Default", "Critical", "Hype", "Sarcastic")
CANONICAL_TWEET_DEFAULT_FORMAT = (
    DEFAULT_TWEET_FORMAT if DEFAULT_TWEET_FORMAT in _FORMAT_GUIDES else "Normal Tweet"
)
CANONICAL_TWEET_DEFAULT_VOICE = (
    DEFAULT_TWEET_VOICE if DEFAULT_TWEET_VOICE in _VOICE_LABELS else "Default"
)


def _tweet_format_options(include_article: bool = True) -> list[str]:
    order = tuple(FORMAT_ORDER or ()) or tuple(_FORMAT_GUIDES.keys()) or _FALLBACK_TWEET_FORMATS
    opts = [
        fmt
        for fmt in order
        if fmt in _FORMAT_GUIDES or fmt in _FALLBACK_TWEET_FORMATS
    ]
    if not opts:
        opts = list(_FALLBACK_TWEET_FORMATS)
    if not include_article:
        opts = [fmt for fmt in opts if fmt != "Article"]
    return opts


def _tweet_voice_options(include_custom: bool = True) -> list[str]:
    opts = list(_VOICE_LABELS.keys()) or list(_FALLBACK_TWEET_VOICES)
    if include_custom:
        for style in load_json("voice_styles.json", []):
            name = style.get("name") if isinstance(style, dict) else ""
            if name and name not in opts:
                opts.append(name)
    return opts


def _normalize_tweet_format(fmt: str | None, *, include_article: bool = True) -> str:
    opts = _tweet_format_options(include_article=include_article)
    if fmt in opts:
        return fmt
    if CANONICAL_TWEET_DEFAULT_FORMAT in opts:
        return CANONICAL_TWEET_DEFAULT_FORMAT
    return opts[0] if opts else CANONICAL_TWEET_DEFAULT_FORMAT


def _normalize_tweet_voice(voice: str | None) -> str:
    opts = _tweet_voice_options(include_custom=True)
    if voice in opts:
        return voice
    return CANONICAL_TWEET_DEFAULT_VOICE


def _tweet_format_short_label(fmt: str) -> str:
    return (fmt or "").replace(" Tweet", "").replace("Long", "Long").strip() or fmt


def _tweet_select_index(options: list[str], current: str | None, fallback: str) -> int:
    value = current if current in options else fallback
    return options.index(value) if value in options else 0


def _get_engagement_lists_path():
    return get_data_dir() / 'engagement_lists.json'

_ENGAGEMENT_DEFAULTS = {
    'Broncos Reporters': {'list_id': '1294328608417177604'},
    'Nuggets':           {'list_id': '1755985316752642285'},
    'Morning Engagement':{'list_id': '2011987998699897046'},
    'Work':              {'list_id': '1182699241329721344'},
}

def load_engagement_lists() -> dict:
    _path = _get_engagement_lists_path()
    if _path.exists():
        try:
            loaded = json.loads(_path.read_text())
            # Guests: return their lists as-is, no Tyler defaults backfilled
            if is_guest():
                return loaded
            migrated = {k: dict(v) for k, v in _ENGAGEMENT_DEFAULTS.items()}
            for k, v in loaded.items():
                if isinstance(v, str):
                    # Restore known list_id from defaults when migrating old handle-string format
                    migrated[k] = {'list_id': _ENGAGEMENT_DEFAULTS.get(k, {}).get('list_id', ''), 'legacy_handles': v}
                else:
                    entry = dict(v)
                    # Restore list_id from defaults if entry exists but list_id is empty
                    if not entry.get('list_id') and k in _ENGAGEMENT_DEFAULTS:
                        entry['list_id'] = _ENGAGEMENT_DEFAULTS[k]['list_id']
                    migrated[k] = entry
            return migrated
        except Exception:
            pass
    # Guests with no file: empty lists (onboarding creates the file)
    if is_guest():
        return {}
    return {k: dict(v) for k, v in _ENGAGEMENT_DEFAULTS.items()}

def save_engagement_lists(lists: dict):
    _get_engagement_lists_path().write_text(json.dumps(lists, indent=2))


def _twitterapi_get_json(endpoint_path: str, params: dict, *, caller: str, timeout: int = 8) -> dict:
    """Fetch TwitterAPI.io JSON directly, then via local proxy if cloud secrets fail."""
    endpoint_path = "/" + str(endpoint_path or "").lstrip("/")
    params = {k: v for k, v in (params or {}).items() if v is not None}
    direct_error = ""
    if TWITTER_API_IO_KEY:
        try:
            resp = requests.get(
                f"https://api.twitterapi.io{endpoint_path}",
                headers={"X-API-Key": TWITTER_API_IO_KEY},
                params=params,
                timeout=timeout,
            )
            if resp.status_code == 200:
                return resp.json()
            direct_error = f"HTTP {resp.status_code}: {resp.text[:240].strip()}"
        except Exception as exc:
            direct_error = str(exc)[:240]
    try:
        query = urllib.parse.urlencode(params)
        proxy_path = endpoint_path + (f"?{query}" if query else "")
        return _proxy_json_request(proxy_path, method="GET", timeout=max(timeout, 15))
    except Exception as exc:
        proxy_error = str(exc)[:240]
        raise RuntimeError(f"TwitterAPI fetch failed via direct/proxy. Direct: {direct_error or 'not configured'} | Proxy: {proxy_error}")


def fetch_tweets_from_list(list_id: str, count: int = 100) -> list:
    """Fetch recent tweets from a Twitter List via twitterapi.io."""
    if not list_id:
        return []
    # Strip full URL to bare numeric ID (e.g. https://x.com/i/lists/1234567890)
    if '/' in list_id:
        import re as _re
        _m = _re.search(r'(\d{10,})', list_id)
        list_id = _m.group(1) if _m else list_id
    try:
        _record_twitter_api_call("list/tweets_timeline", "fetch_tweets_from_list", extra={"list_id": str(list_id)})
        data = _twitterapi_get_json(
            "/twitter/list/tweets_timeline",
            {"listId": list_id},
            caller="fetch_tweets_from_list",
        )
        return data.get("tweets", []) if isinstance(data, dict) else []
    except Exception as exc:
        _append_debug_event("twitter_fetch", "error", f"list fetch failed {exc}", {"list_id": str(list_id)})
        pass
    return []


def fetch_tweets(query: str, count: int = 50) -> list:
    if not query:
        return []
    try:
        _record_twitter_api_call("tweet/advanced_search", "fetch_tweets", query=query, extra={"count": min(count, 100)})
        data = _twitterapi_get_json(
            "/twitter/tweet/advanced_search",
            {"query": query, "queryType": "Latest", "count": min(count, 100), "cursor": ""},
            caller="fetch_tweets",
        )
        tweets = data.get("tweets", []) if isinstance(data, dict) else []
        return tweets[:count]
    except Exception as exc:
        _append_debug_event("twitter_fetch", "error", f"search fetch failed {exc}", {"query": query[:140]})
        pass
    return []


def fetch_user_info(handle: str) -> dict:
    if not TWITTER_API_IO_KEY:
        return {}
    try:
        resp = requests.get(
            "https://api.twitterapi.io/twitter/user/info",
            headers={"X-API-Key": TWITTER_API_IO_KEY},
            params={"userName": handle},
            timeout=8,
        )
        if resp.status_code == 200:
            return resp.json().get("data", {})
    except Exception:
        pass
    return {}


