import hashlib as _hl

try:
    _OWNER_PW = st.secrets["OWNER_PASSWORD"]
except (KeyError, FileNotFoundError):
    _OWNER_PW = ""

_ACCOUNTS_PATH = Path(os.path.expanduser("~/.openclaw/guests/accounts.json"))

def _load_accounts() -> dict:
    if _ACCOUNTS_PATH.exists():
        try:
            return json.loads(_ACCOUNTS_PATH.read_text())
        except Exception:
            pass
    return {}

def _save_accounts(data: dict):
    _ACCOUNTS_PATH.parent.mkdir(parents=True, exist_ok=True)
    _ACCOUNTS_PATH.write_text(json.dumps(data, indent=2, default=str))

def _hash_pw(username: str, password: str) -> str:
    return _hl.sha256(f"mp_{username}_{password}".encode()).hexdigest()


_OWNER_TOKEN = _hl.sha256(f"mp_owner_{_OWNER_PW}".encode()).hexdigest()[:16] if _OWNER_PW else ""
_CANONICAL_ORIGIN = os.getenv("POSTASCEND_CANONICAL_ORIGIN", "http://localhost:8501").strip()
_AUTH_RESTORE_COMPONENT = None

if "auth_role" not in st.session_state:
    st.session_state["auth_role"] = None


def _clear_auth_session():
    st.session_state["auth_role"] = None
    st.session_state["_clear_client_auth"] = True
    for key in [
        "_auth_token",
        "auth_username",
        "user_handle",
        "user_display_name",
        "user_avatar",
        "onboarding_complete",
        "onboarding_step",
    ]:
        st.session_state.pop(key, None)
    for key in ["token", "user", "guest_id", "logout"]:
        if key in st.query_params:
            del st.query_params[key]


if st.query_params.get("logout") == "1":
    _clear_auth_session()


def _read_client_auth_component() -> str:
    global _AUTH_RESTORE_COMPONENT
    if _AUTH_RESTORE_COMPONENT is None:
        import streamlit.components.v1 as _stc_restore

        _AUTH_RESTORE_COMPONENT = _stc_restore.declare_component(
            "auth_restore",
            path=str(Path(__file__).resolve().parent / "components" / "auth_restore"),
        )
    return _AUTH_RESTORE_COMPONENT(default="", key="auth_restore") or ""


def _render_client_auth_bridge(mode: str, payload: dict | None = None, invalid_qp: bool = False):
    import streamlit.components.v1 as _stc_auth

    _payload_json = json.dumps(payload or {}, separators=(",", ":")).replace("</", "<\\/")
    _mode_json = json.dumps(mode)
    _invalid_json = "true" if invalid_qp else "false"
    _stc_auth.html(
        """<script>
(function(){
  var mode = __MODE__;
  var payload = __PAYLOAD__;
  var invalidQP = __INVALID_QP__;
  var KEY = "mp_auth";

  function windowChain(){
    var wins = [window];
    try{ if(window.parent && wins.indexOf(window.parent) === -1) wins.push(window.parent); }catch(e){}
    try{ if(window.top && wins.indexOf(window.top) === -1) wins.push(window.top); }catch(e){}
    return wins;
  }

  function usableUrl(win){
    try{
      var url = new URL(win.location.href);
      if(url.protocol === "http:" || url.protocol === "https:") return url;
    }catch(e){}
    return null;
  }

  function hostWindow(){
    // Streamlit Cloud can wrap the app; use the first accessible HTTP frame.
    var wins = windowChain();
    for(var i=1; i<wins.length; i++){
      if(usableUrl(wins[i])) return wins[i];
    }
    if(usableUrl(window)) return window;
    return null;
  }

  function writeCookie(value, maxAge){
    windowChain().forEach(function(win){
      try{
        var cookie = "mp_auth=" + encodeURIComponent(value) + "; path=/; SameSite=Lax";
        if(typeof maxAge === "number") cookie += "; max-age=" + maxAge;
        if(win.location && win.location.protocol === "https:") cookie += "; Secure";
        win.document.cookie = cookie;
      }catch(e){}
    });
  }

  function readCookie(){
    var prefix = "mp_auth=";
    var wins = windowChain();
    for(var w=0; w<wins.length; w++){
      try{
        var parts = wins[w].document.cookie.split(";");
        for(var i=0;i<parts.length;i++){
          var part = parts[i].trim();
          if(part.indexOf(prefix) === 0) return decodeURIComponent(part.slice(prefix.length));
        }
      }catch(e){}
    }
    return "";
  }

  function writeLocal(value){
    windowChain().forEach(function(win){
      try{ win.localStorage.setItem(KEY, value); }catch(e){}
      try{ win.sessionStorage.setItem(KEY, value); }catch(e){}
    });
  }

  function readLocal(){
    var wins = windowChain();
    for(var i=0;i<wins.length;i++){
      try{
        var raw = wins[i].localStorage.getItem(KEY) || wins[i].sessionStorage.getItem(KEY);
        if(raw) return raw;
      }catch(e){}
    }
    return "";
  }

  function clearStoredAuth(){
    windowChain().forEach(function(win){
      try{ win.localStorage.removeItem(KEY); }catch(e){}
      try{ win.sessionStorage.removeItem(KEY); }catch(e){}
    });
    try{ writeCookie("", 0); }catch(e){}
  }

  function stripAuthParams(){
    try{
      var hostWin = hostWindow();
      if(!hostWin) return;
      var current = new URL(hostWin.location.href);
      ["token", "user", "guest_id"].forEach(function(key){ current.searchParams.delete(key); });
      hostWin.location.replace(current.toString());
    }catch(e){}
  }

  if(mode === "persist"){
    try{
      var value = JSON.stringify(payload || {});
      writeLocal(value);
      writeCookie(value, 31536000);
    }catch(e){}
    return;
  }

  if(mode === "clear"){
    clearStoredAuth();
    stripAuthParams();
    return;
  }

  if(mode === "restore"){
    try{
      var hostWin = hostWindow();
      if(!hostWin) return;
      var current = new URL(hostWin.location.href);
      if(current.searchParams.get("token")) return;
      var raw = readLocal() || readCookie();
      if(!raw) return;
      var saved = JSON.parse(raw);
      if(!saved || !saved.token || !saved.role) return;
      current.searchParams.set("token", saved.token);
      if(saved.user) current.searchParams.set("user", saved.user);
      else current.searchParams.delete("user");
      if(saved.guest_id) current.searchParams.set("guest_id", saved.guest_id);
      hostWin.location.replace(current.toString());
    }catch(e){}
    if(invalidQP){
      stripAuthParams();
    }
  }
})();
</script>"""
        .replace("__MODE__", _mode_json)
        .replace("__PAYLOAD__", _payload_json)
        .replace("__INVALID_QP__", _invalid_json),
        height=0,
    )


def _get_request_cookie(name: str) -> str:
    try:
        raw = st.context.cookies.get(name, "")
        if raw:
            return raw
    except Exception:
        pass
    try:
        from http.cookies import SimpleCookie

        headers = getattr(st.context, "headers", {}) or {}
        cookie_header = ""
        for key in ("cookie", "Cookie"):
            try:
                cookie_header = headers.get(key, "")
            except Exception:
                cookie_header = ""
            if cookie_header:
                break
        if not cookie_header:
            return ""
        jar = SimpleCookie()
        jar.load(cookie_header)
        morsel = jar.get(name)
        return morsel.value if morsel else ""
    except Exception:
        return ""


def _restore_auth_payload(raw: str | dict | None) -> bool:
    if not raw:
        return False
    try:
        if isinstance(raw, dict):
            data = raw
        else:
            data = json.loads(urllib.parse.unquote(str(raw)))
        role = data.get("role", "")
        token = data.get("token", "")
        user = data.get("user", "")
        if role == "owner" and token == _OWNER_TOKEN:
            st.session_state["auth_role"] = "owner"
            st.session_state["auth_username"] = "owner"
            st.query_params["token"] = token
            st.query_params["user"] = "owner"
            return True
        if role == "guest" and user:
            accounts = _load_accounts()
            if user in accounts and accounts[user].get("token") == token:
                st.session_state["auth_role"] = "guest"
                st.session_state["auth_username"] = user
                st.query_params["token"] = token
                st.query_params["user"] = user
                guest_id = accounts[user].get("guest_id", "")
                if guest_id:
                    st.query_params["guest_id"] = guest_id
                return True
    except Exception:
        pass
    return False


def _render_canonical_origin_bridge():
    if not _CANONICAL_ORIGIN:
        return

    _origin_json = json.dumps(_CANONICAL_ORIGIN)
    st.html(
        """<script>
(function(){
  try{
    var canonical = new URL(__CANONICAL__);
    var current = new URL(window.parent.location.href);
    var isCloud = /streamlit\\.app$/i.test(current.hostname);
    var isMobile = false;
    try{
      isMobile = window.parent.matchMedia("(max-width: 768px)").matches;
    }catch(e){}
    if(isCloud || isMobile) return;
    if(current.origin === canonical.origin) return;
    canonical.pathname = current.pathname;
    canonical.search = current.search;
    canonical.hash = current.hash;
    window.location.replace(canonical.toString());
  }catch(e){}
})();
</script>""".replace("__CANONICAL__", _origin_json),
        unsafe_allow_javascript=True,
    )


_render_canonical_origin_bridge()

