def _signal_query_chunks(query: str, chunk_size: int = 8) -> list[str]:
    """Split large source-heavy Twitter queries into provider-safe chunks."""
    import re as _re

    handles = _re.findall(r"from:[A-Za-z0-9_]+", query or "")
    if len(handles) <= chunk_size:
        return [query]

    chunks = [" OR ".join(handles[i:i + chunk_size]) for i in range(0, len(handles), chunk_size)]
    if query.strip().startswith("("):
        source_block = "(" + " OR ".join(handles) + ")"
        if source_block in query:
            return [query.replace(source_block, f"({chunk})") for chunk in chunks]
    return chunks


def _fetch_signals(query, count=30, max_age_hours=48, pages=1, start_cursor=""):
    """Fetch tweets via TwitterAPI.io advanced_search with pagination, filtering stale results.
    Returns (tweets, last_cursor) tuple."""
    global _LAST_SIGNALS_ERROR
    try:
        from datetime import timedelta, timezone
        all_tweets = []
        last_cursor = ""
        query_chunks = _signal_query_chunks(query)
        per_chunk_count = max(10, min(100, count if len(query_chunks) == 1 else max(10, count // len(query_chunks) + 5)))
        for chunk_query in query_chunks:
            cursor = start_cursor if len(query_chunks) == 1 else ""
            for _ in range(pages if len(query_chunks) == 1 else 1):
                _record_twitter_api_call("tweet/advanced_search", "signals_fetch", query=chunk_query, extra={"count": per_chunk_count, "cursor": bool(cursor)})
                data = _twitterapi_get_json(
                    "/twitter/tweet/advanced_search",
                    {"query": chunk_query, "queryType": "Latest", "count": per_chunk_count, "cursor": cursor},
                    caller="signals_fetch",
                )
                _LAST_SIGNALS_ERROR = {"status": "", "detail": "", "at": ""}
                all_tweets.extend(data.get("tweets", []) if isinstance(data, dict) else [])
                cursor = data.get("next_cursor", "") if isinstance(data, dict) else ""
                last_cursor = cursor or last_cursor
                if not cursor:
                    break
        # Filter to recent tweets only
        cutoff = datetime.now(timezone.utc) - timedelta(hours=max_age_hours)
        fresh = []
        for t in all_tweets:
            try:
                created = datetime.strptime(t.get("createdAt", ""), "%a %b %d %H:%M:%S %z %Y")
                if created >= cutoff:
                    fresh.append(t)
            except (ValueError, TypeError):
                pass
        return fresh, last_cursor
    except Exception as e:
        detail = str(e)[:240]
        status = "credits_depleted" if "Credits is not enough" in detail else "exception"
        _LAST_SIGNALS_ERROR = {
            "status": status,
            "detail": detail,
            "at": datetime.now().isoformat(timespec="seconds"),
        }
    return [], ""


def _relative_time(created_at_str):
    """Convert createdAt to '2m ago', '1h ago', '3d ago'. Handles both Twitter format and ISO."""
    if not created_at_str:
        return "time unknown"
    try:
        from datetime import timezone
        # Twitter format: "Thu Nov 23 03:31:24 +0000 2023"
        try:
            created = datetime.strptime(created_at_str, "%a %b %d %H:%M:%S %z %Y")
        except ValueError:
            # ISO fallback: "2026-03-29T12:00:00Z"
            created = datetime.fromisoformat(created_at_str.replace("Z", "+00:00"))
        delta = datetime.now(timezone.utc) - created
        secs = int(delta.total_seconds())
        if secs < 0:
            return "just now"
        elif secs < 60:
            return f"{secs}s ago"
        elif secs < 3600:
            return f"{secs // 60}m ago"
        elif secs < 86400:
            return f"{secs // 3600}h ago"
        else:
            return f"{secs // 86400}d ago"
    except Exception:
        return "time unknown"


def _estimate_trend_pill(tweet):
    """Infer Rising / Peak / Fading from the tweet itself with no extra API call."""
    if not isinstance(tweet, dict):
        return "peak", "Peak"
    try:
        created = datetime.strptime(tweet.get("createdAt", ""), "%a %b %d %H:%M:%S %z %Y")
        age_hours = max(0, (datetime.now(created.tzinfo) - created).total_seconds() / 3600)
    except Exception:
        age_hours = 6

    replies = int(tweet.get("replyCount", 0) or 0)
    rts = int(tweet.get("retweetCount", 0) or 0)
    qts = int(tweet.get("quoteCount", 0) or 0)
    engagement = replies + rts + qts

    if age_hours <= 2 and engagement >= 15:
        return "rising", "Rising"
    if age_hours <= 12 and engagement >= 5:
        return "peak", "Peak"
    return "fading", "Fading"


_STOP_WORDS = {"the", "a", "an", "is", "are", "was", "were", "in", "on", "at", "to", "for", "of", "and", "or", "with", "this", "that", "from", "by", "has", "have", "had", "his", "her", "its", "will", "be", "been"}

def _dedup_signals(tweets, min_overlap=3):
    """Collapse tweets about the same story, keeping the one with most replies."""
    if not tweets:
        return tweets
    kept = []
    for tw in tweets:
        words = set(w.lower() for w in re.findall(r'[A-Za-z]+', tw.get("text", "")) if len(w) > 2 and w.lower() not in _STOP_WORDS)
        is_dup = False
        for i, (ktw, kwords) in enumerate(kept):
            overlap = len(words & kwords)
            if overlap >= min_overlap:
                # Keep the one with more replies
                if tw.get("replyCount", 0) > ktw.get("replyCount", 0):
                    kept[i] = (tw, words | kwords)
                is_dup = True
                break
        if not is_dup:
            kept.append((tw, words))
    return [tw for tw, _ in kept]


def _quick_sport_tag(text):
    """Fast sport detection from text only — for card display pills."""
    _l = text.lower()
    _nfl = ["broncos", "nfl", "bo nix", "sean payton", "paton", "draft", "football", "owners meetings", "waddle", "sutton"]
    _nba = ["nuggets", "jokic", "jamal murray", "aaron gordon", "nba", "basketball", "halftime", "tipoff"]
    _nhl = ["avalanche", "avs", "mackinnon", "makar", "nhl", "hockey"]
    _cfb = ["buffs", "cu buffs", "deion", "shedeur"]
    scores = {"NFL": sum(1 for s in _nfl if s in _l), "NBA": sum(1 for s in _nba if s in _l),
              "NHL": sum(1 for s in _nhl if s in _l), "CFB": sum(1 for s in _cfb if s in _l)}
    best = max(scores, key=scores.get)
    return best if scores[best] > 0 else None

