def page_podcast():
    if not is_owner():
        st.session_state.current_page = "Creator Studio"
        st.query_params["page"] = "Creator Studio"
        if "podcast_state" in st.query_params:
            del st.query_params["podcast_state"]
        if "podcast_run" in st.query_params:
            del st.query_params["podcast_run"]
        st.rerun()

    actor = st.session_state.get("auth_username", "") or get_current_handle() or "owner"
    store = _load_podcast_runs_store()
    runs = store["runs"]
    run_lookup = {run["id"]: run for run in runs}
    requested_run_id = str(st.query_params.get("podcast_run", "")).strip()
    requested_state = str(st.query_params.get("podcast_state", "")).strip()

    def _save_podcast_and_rerun(updated_store: dict, run_id: str = "") -> None:
        saved = _save_podcast_runs_store(updated_store)
        active_run_id = run_id or saved.get("active_run_id", "")
        if active_run_id:
            st.session_state["_podcast_last_run_id"] = active_run_id
            active_run = next((item for item in saved["runs"] if item["id"] == active_run_id), None)
            st.query_params["podcast_run"] = active_run_id
            if active_run:
                st.query_params["podcast_state"] = active_run["current_state"]
        else:
            if "podcast_run" in st.query_params:
                del st.query_params["podcast_run"]
            st.query_params["podcast_state"] = requested_state or get_podcast_dashboard_content(None)["current_state"]
        st.rerun()

    def _create_hq_run(
        *,
        title: str,
        discord_reference: str,
        run_mode: str,
        episode_code: str = "",
        source_path: str = "",
        publish_window: str = "",
        notes: str = "",
    ) -> None:
        clean_title = title.strip()
        clean_source = source_path.strip()
        if not clean_title and not clean_source:
            st.warning("Add a video link, local file path, or run title before starting the podcast workflow.")
            return
        normalized_source = podcast_tracker.canonical_source_key(clean_source)
        normalized_discord = discord_reference.strip().lower()
        existing_run = next(
            (
                candidate
                for candidate in runs
                if (normalized_source and podcast_tracker.canonical_source_key(candidate.get("source_path", "")) == normalized_source)
                or (normalized_discord and candidate.get("discord_reference", "").strip().lower() == normalized_discord)
            ),
            None,
        )
        if existing_run:
            updated_store = podcast_tracker.deepcopy_store(store)
            podcast_tracker.set_active_run(updated_store, existing_run["id"])
            st.session_state["_podcast_flash_message"] = {"level": "success", "text": f"Opened the existing run for this link instead of creating a duplicate: {existing_run['title']}"}
            _save_podcast_and_rerun(updated_store, existing_run["id"])
            return
        updated_store = podcast_tracker.deepcopy_store(store)
        new_run = podcast_tracker.create_run(
            updated_store,
            actor=actor,
            title=clean_title or podcast_tracker._suggest_title_from_source(clean_source),
            episode_code=episode_code,
            source_path=source_path,
            run_mode=run_mode,
            discord_reference=discord_reference,
            publish_window=publish_window,
            notes=notes,
        )
        if run_mode == "local" and clean_source and "://" not in clean_source:
            try:
                start_result = _podcast_proxy_start(new_run["id"], clean_source, new_run["title"])
                job = start_result.get("job", {})
                podcast_tracker.transition_run(
                    updated_store,
                    run_id=new_run["id"],
                    actor=actor,
                    state="transcribing",
                    note=f"Independent HQ runner started local transcription job ({job.get('status', 'queued')}).",
                )
                st.session_state["_podcast_flash_message"] = {"level": "success", "text": "Local podcast run started on your proxy host. Transcript generation is now running independently of Discord."}
            except Exception as exc:
                podcast_tracker.transition_run(
                    updated_store,
                    run_id=new_run["id"],
                    actor=actor,
                    state="blocked_manual_fix",
                    blocker=f"Local podcast start failed: {exc}",
                    note="Independent HQ runner failed to start on the proxy host.",
                )
                st.session_state["_podcast_flash_message"] = {"level": "error", "text": f"Podcast run was created, but local start failed: {exc}"}
        elif clean_source:
            st.session_state["_podcast_flash_message"] = {"level": "warning", "text": "Run created. This mode tracks the workflow, but it does not start the local runner automatically."}
        else:
            st.session_state["_podcast_flash_message"] = {"level": "warning", "text": "Run created. Add a local source path when you are ready to launch the independent runner."}
        _save_podcast_and_rerun(updated_store, new_run["id"])

    def _render_podcast_start_form(form_key: str = "podcast_wizard_start_form") -> None:
        with st.form(form_key, clear_on_submit=True):
            wizard_mode = st.radio(
                "How are you starting this run?",
                (
                    "Start From Local Video",
                    "Track External Video URL",
                    "Mirror Discord Run",
                ),
                horizontal=True,
                key=f"{form_key}_mode",
            )
            wizard_title = st.text_input("Episode Title (Optional)", placeholder="Leave blank if you do not know it yet", key=f"{form_key}_title")
            wizard_source = ""
            wizard_discord = ""
            if wizard_mode == "Start From Local Video":
                wizard_source = st.text_input("Local Video File Path", placeholder=r"C:\Videos\episode_042.mp4", key=f"{form_key}_source_local")
                st.caption("This is the full independent HQ path. HQ will run the transcript and clip flow itself.")
            elif wizard_mode == "Track External Video URL":
                wizard_source = st.text_input("Video URL", placeholder="https://youtu.be/...", key=f"{form_key}_source_url")
                st.caption("Use this when you want HQ to track the run but you are not running the local transcript worker from a file path.")
            else:
                wizard_discord = st.text_input("Discord Thread Link", placeholder="https://discord.com/channels/...", key=f"{form_key}_discord")
                st.caption("Use this when you only want HQ to mirror a Discord-first workflow.")
            wizard_start = st.form_submit_button(
                "Start Podcast Workflow" if wizard_mode != "Mirror Discord Run" else "Create Discord Mirror Run",
                type="primary",
                use_container_width=True,
            )
        if wizard_start:
            if wizard_mode == "Mirror Discord Run" and not wizard_discord.strip():
                st.error("Paste the Discord thread link first.")
                return
            if wizard_mode != "Mirror Discord Run" and not wizard_source.strip():
                st.error("Add the video path or URL first.")
                return
            if wizard_mode == "Start From Local Video" and not _podcast_is_local_source_path(wizard_source):
                st.error("Use a real local file path for this mode.")
                return
            if wizard_mode == "Track External Video URL" and _podcast_is_local_source_path(wizard_source):
                st.error("Use a real URL for this mode.")
                return
            st.session_state["_podcast_wizard_start_new"] = False
            st.session_state["_podcast_wizard_open"] = True
            _create_hq_run(
                title=wizard_title,
                discord_reference=wizard_discord,
                run_mode="local" if wizard_mode == "Start From Local Video" else ("url" if wizard_mode == "Track External Video URL" else "discord"),
                source_path=wizard_source,
                notes=f"Started from the Podcast wizard ({wizard_mode}).",
            )

    def _podcast_card_html(label: str, value: str, meta: str) -> str:
        return (
            '<div class="podcast-status-card">'
            f'<div class="podcast-status-kicker">{html.escape(label)}</div>'
            f'<div class="podcast-status-value">{html.escape(value)}</div>'
            f'<div class="podcast-status-meta">{html.escape(meta)}</div>'
            '</div>'
        )

    def _podcast_run_label(run: dict) -> str:
        state_label = _PODCAST_STATE_LABELS.get(run["current_state"], run["current_state"])
        code = f" · {run['episode_code']}" if run.get("episode_code") else ""
        return f"{run['title']}{code} · {state_label}"

    def _podcast_value_html(value: str, empty_label: str = "Not Set", link_label: str = "Open Link") -> str:
        clean = _podcast_clean_display_value(value)
        if not clean:
            return html.escape(empty_label)
        if clean.startswith(("http://", "https://")):
            safe_href = html.escape(clean, quote=True)
            safe_text = html.escape(link_label)
            safe_title = html.escape(clean, quote=True)
            return f'<a href="{safe_href}" target="_blank" title="{safe_title}" style="color:#2DD4BF;text-decoration:none;">{safe_text}</a>'
        return html.escape(clean)

    def _set_podcast_section(run_id: str, section_name: str) -> None:
        st.session_state[f"podcast_section_{run_id}"] = section_name

    def _podcast_artifact_has_content(run_data: dict, artifact_id: str) -> bool:
        return podcast_workflow.artifact_has_content(run_data, artifact_id)

    def _podcast_packaging_artifact_ids() -> tuple[str, ...]:
        return tuple(podcast_workflow.PACKAGING_ARTIFACT_IDS)

    def _podcast_packaging_ready(run_data: dict) -> bool:
        return podcast_workflow.packaging_ready(run_data)

    def _podcast_gate1_ready(run_data: dict) -> bool:
        return podcast_workflow.gate1_ready(run_data)

    def _podcast_gate2_ready(run_data: dict) -> bool:
        return podcast_workflow.gate2_ready(run_data)

    def _podcast_has_delivery_receipt(run_data: dict) -> bool:
        return podcast_workflow.has_delivery_receipt(run_data)

    def _podcast_parse_json_response(raw_text: str) -> dict:
        clean = (raw_text or "").strip()
        if not clean:
            raise ValueError("The AI returned an empty response.")
        fenced = re.search(r"```(?:json)?\s*(\{.*\})\s*```", clean, re.DOTALL)
        if fenced:
            clean = fenced.group(1).strip()
        start = clean.find("{")
        end = clean.rfind("}")
        if start != -1 and end != -1 and end >= start:
            clean = clean[start:end + 1]
        return json.loads(clean)

    def _podcast_call_model(prompt: str, system: str, *, max_tokens: int, model: str, timeout: int) -> str:
        try:
            return _call_claude_proxy(prompt, system, max_tokens=max_tokens, model=model, timeout=timeout)
        except Exception:
            return _call_claude_direct(prompt, system, max_tokens=max_tokens, model=model, timeout=min(timeout, 90))

    def _podcast_user_error_text(raw_error: str) -> str:
        clean = str(raw_error or "").strip()
        lowered = clean.lower()
        if not clean:
            return "Something went wrong. Try again in a moment."
        if "source file not found" in lowered:
            return "HQ could not find that local video file on your computer. Double-check the file path and try again."
        if "already running" in lowered:
            return "That job is already running. Wait a moment and press the refresh button instead of starting it again."
        if "transcription must complete before clips can be generated" in lowered:
            return "HQ is still waiting for the transcript to finish before it can make clips."
        if "forbidden" in lowered or "proxy" in lowered and "http error 403" in lowered:
            return "HQ could not reach your local runner securely. Refresh once, and if it still fails, restart the local proxy."
        if "clip generation failed" in lowered or "clipsai" in lowered:
            return "HQ could not finish making shorts clips. Try the clip step again, and if it keeps failing, open the Advanced Workspace for details."
        return clean

    def _podcast_trim_prompt_text(text: str, max_chars: int = 28000) -> str:
        clean = str(text or "").strip()
        if len(clean) <= max_chars:
            return clean
        head_len = max_chars // 2
        tail_len = max_chars // 3
        head = clean[:head_len].rsplit(" ", 1)[0].strip()
        tail = clean[-tail_len:].split(" ", 1)[-1].strip()
        return f"{head}\n\n[... transcript trimmed for prompt length ...]\n\n{tail}"

    def _podcast_generate_packaging_artifacts(updated_store: dict, run_data: dict) -> None:
        transcript_text = str(run_data["artifacts"]["transcript"].get("text", "")).strip()
        if not transcript_text:
            raise ValueError("Transcript content is missing, so packaging suggestions cannot be generated yet.")
        chapters_text = str(run_data["artifacts"]["chapters"].get("text", "")).strip()
        transcript_for_prompt = _podcast_trim_prompt_text(transcript_text)
        chapters_for_prompt = chapters_text or "No chapter text supplied yet."
        system = (
            get_system_for_voice("Default", "")
            + "\n\n"
            + "You are Booth, Tyler's podcast and YouTube packaging agent. "
            + "Match the unpublished workflow rules exactly. "
            + "Return strict JSON only. No markdown. No explanation. "
            + "Never use emojis. Never use third-person attribution like 'Tyler says'. "
            + "Never use 'we' for team framing; say 'the Broncos'. "
            + "Always spell George Paton exactly as George Paton. Never write George Peyton. "
            + "Prefer plain punctuation over em dash or en dash separators. "
            + "Never return notes about what the copy should be. Return the actual copy."
        )
        gate_prompt = f"""
Generate the Gate 1 packaging options and cleaned chapters for this unpublished podcast run.

Run title:
{run_data['title']}

Transcript:
{transcript_for_prompt}

Rough chapter/timestamp anchors:
{chapters_for_prompt}

Rules:
- Return exactly 3 video title options.
- 8 words max per title. Count the words.
- Preserve a curiosity gap.
- If the viewer can explain the exact event without watching, rewrite it.
- One capitalized emotional anchor is okay.
- Return exactly 3 thumbnail text options.
- Thumbnail text must be 2-3 words max, no team names, and not a question.
- Return 5-8 cleaned chapter lines.
- Format each chapter line exactly like `0:00 Intro`.
- Use the supplied timestamps as anchors when possible.
- No emojis anywhere.

Return strict JSON with exactly these keys:
{{
  "title_options": ["3 video title options"],
  "thumbnail_text_options": ["3 thumbnail text options"],
  "chapters": ["0:00 Intro", "2:01 Another chapter"]
}}
""".strip()

        with st.spinner("Generating podcast packaging suggestions..."):
            gate_payload = _podcast_parse_json_response(
                _podcast_call_model(gate_prompt, system, max_tokens=1400, model="claude-sonnet-4-6", timeout=120)
            )

        title_candidates = [str(item).strip() for item in gate_payload.get("title_options", []) if str(item).strip()]
        thumbnail_options = [str(item).strip() for item in gate_payload.get("thumbnail_text_options", []) if str(item).strip()]
        cleaned_chapters = [str(item).strip() for item in gate_payload.get("chapters", []) if str(item).strip()]
        if not title_candidates or not thumbnail_options or not cleaned_chapters:
            raise ValueError("The AI response was missing required Gate 1 packaging suggestions.")

        formatted_titles = "\n".join(f"{idx + 1}. {item}" for idx, item in enumerate(title_candidates[:3]))
        formatted_thumbnails = "\n".join(f"{idx + 1}. {item}" for idx, item in enumerate(thumbnail_options[:3]))
        formatted_chapters = "\n".join(cleaned_chapters[:8])

        metadata_prompt = f"""
Generate the longform metadata for this unpublished podcast run.

Run title:
{run_data['title']}

Transcript:
{transcript_for_prompt}

Approved chapter list:
{formatted_chapters}

Rules:
- Write one real YouTube description, not options.
- First line is a strong hook and must not repeat the title.
- Insert the exact chapter list after the hook.
- Then write 3-4 short conversational paragraphs in Tyler's voice.
- Include exactly this line near the end: `Follow Tyler: https://x.com/Tyler_Polumbus`
- End with one engagement question.
- Generate 15-20 tags with no `#`.
- Remove generic filler like `football` and `nfl`.
- Generate one actual episode tweet draft, not multiple options.
- No hashtags.
- No URL.
- No unverified claims.
- Never say `Tyler says`.
- Never say `we` for team framing.
- No emojis anywhere.

Reference format:
The Jalen Waddell move already happened. Now the Broncos have to prove they know exactly what comes next with No. 62.

0:00 Why No. 62 changes everything
2:01 George Paton's track record in this range

[short conversational paragraphs]

Follow Tyler: https://x.com/Tyler_Polumbus

Who would you target at No. 62, and is there anybody you would actually move up for?

Return strict JSON with exactly these keys:
{{
  "description": "full YouTube description with chapter lines inserted",
  "tags": ["15 to 20 relevant tags"],
  "episode_tweet": "one actual episode tweet draft"
}}
""".strip()

        with st.spinner("Generating metadata and episode tweet..."):
            metadata_payload = _podcast_parse_json_response(
                _podcast_call_model(metadata_prompt, system, max_tokens=1800, model="claude-sonnet-4-6", timeout=120)
            )

        tags = [str(item).strip() for item in metadata_payload.get("tags", []) if str(item).strip()]
        formatted_tags = ", ".join(tags[:20])
        description_text = str(metadata_payload.get("description", "")).strip()
        episode_tweet = str(metadata_payload.get("episode_tweet", "")).strip()
        if not description_text or not episode_tweet or not tags:
            raise ValueError("The AI response was missing required metadata or tweet fields.")

        clip_prompt = f"""
Generate the per-clip copy bundles for this unpublished podcast run.

Run title:
{run_data['title']}

Transcript:
{transcript_for_prompt}

Approved chapter list:
{formatted_chapters}

Rules:
- Return exactly 3 clip packages if the transcript supports them. Otherwise return the strongest 2.
- Each clip must have a plausible time range.
- Each clip package must include the actual copy bundle, not notes.
- Shorts title should feel like a real YouTube Shorts title.
- Shorts description should point back to the full episode.
- Instagram caption must end exactly with `Watch full video - link in bio`.
- Clip tweet must have no hashtags and no invented facts.
- Never say `Tyler says`.
- Never say `we` for team framing.
- No emojis anywhere.

Reference clip copy shape:
Shorts title: The Broncos Still Need This Weapon
Shorts description: Evan Engram can help, but Denver still needs a real difference-maker at tight end.
Instagram caption ending: Watch full video - link in bio

Return strict JSON with exactly these keys:
{{
  "clip_packages": [
    {{
      "title": "HQ clip label",
      "time_range": "MM:SS-MM:SS",
      "reason": "why this clip works",
      "tweet": "actual tweet text",
      "shorts_title": "actual YouTube Shorts title",
      "shorts_description": "actual Shorts description",
      "shorts_tags": ["8 to 12 tags"],
      "instagram_caption": "actual IG caption ending with Watch full video - link in bio"
    }}
  ]
}}
""".strip()

        with st.spinner("Generating per-clip social packages..."):
            clip_payload = _podcast_parse_json_response(
                _podcast_call_model(clip_prompt, system, max_tokens=1800, model="claude-sonnet-4-6", timeout=120)
            )

        clip_suggestions = clip_payload.get("clip_packages", [])

        clip_lines = []
        for idx, clip in enumerate(clip_suggestions[:3]):
            if not isinstance(clip, dict):
                continue
            clip_title = str(clip.get("title", "")).strip()
            clip_range = str(clip.get("time_range", "")).strip()
            clip_reason = str(clip.get("reason", "")).strip()
            clip_tweet = str(clip.get("tweet", "")).strip()
            shorts_title = str(clip.get("shorts_title", "")).strip()
            shorts_description = str(clip.get("shorts_description", "")).strip()
            shorts_tags = [str(item).strip() for item in clip.get("shorts_tags", []) if str(item).strip()]
            instagram_caption = str(clip.get("instagram_caption", "")).strip()
            if instagram_caption and not instagram_caption.endswith("Watch full video - link in bio"):
                instagram_caption = instagram_caption.rstrip() + "\n\nWatch full video - link in bio"
            if clip_title or clip_range or clip_reason or clip_tweet or shorts_title or shorts_description or instagram_caption:
                clip_lines.append(
                    "\n".join(
                        line
                        for line in [
                            f"Clip {idx + 1}: {clip_title}" if clip_title else f"Clip {idx + 1}",
                            f"Time Range: {clip_range}" if clip_range else "",
                            f"Why This Clip: {clip_reason}" if clip_reason else "",
                            "",
                            "TWEET:" if clip_tweet else "",
                            clip_tweet if clip_tweet else "",
                            "",
                            "YOUTUBE SHORTS:" if (shorts_title or shorts_description or shorts_tags) else "",
                            f"Title: {shorts_title}" if shorts_title else "",
                            f"Description: {shorts_description}" if shorts_description else "",
                            f"Tags: {', '.join(shorts_tags[:12])}" if shorts_tags else "",
                            "",
                            "INSTAGRAM REEL:" if instagram_caption else "",
                            instagram_caption if instagram_caption else "",
                        ]
                        if line
                    )
                )
        formatted_clips = "\n\n".join(clip_lines)
        if not formatted_clips:
            raise ValueError("The AI response did not include enough packaging detail to save.")

        artifact_updates = {
            "title": (formatted_titles, run_data["artifacts"]["title"].get("path", ""), "Generated Gate 1 video title options using the unpublished workflow rules."),
            "thumbnail_text": (formatted_thumbnails, run_data["artifacts"]["thumbnail_text"].get("path", ""), "Generated Gate 1 thumbnail text options using the unpublished workflow rules."),
            "chapters": (formatted_chapters, run_data["artifacts"]["chapters"].get("path", ""), "Generated cleaned chapters using the unpublished workflow format."),
            "description": (description_text, run_data["artifacts"]["description"].get("path", ""), "Generated full YouTube description using the unpublished workflow format."),
            "tags": (formatted_tags, run_data["artifacts"]["tags"].get("path", ""), "Generated episode tags using the unpublished workflow rules."),
            "tweet": (episode_tweet, run_data["artifacts"]["tweet"].get("path", ""), "Generated the episode tweet draft using the unpublished workflow rules."),
            "clips": (formatted_clips, run_data["artifacts"]["clips"].get("path", ""), "Generated per-clip Shorts, X, and Instagram copy bundles using the unpublished workflow rules."),
        }
        for artifact_id, (text_value, path_value, notes_value) in artifact_updates.items():
            podcast_tracker.update_artifact(
                updated_store,
                run_id=run_data["id"],
                artifact_id=artifact_id,
                actor=actor,
                text=text_value,
                path=path_value,
                status="draft",
                notes=notes_value,
            )

    def _guided_actions_for_run(run: dict) -> list[dict]:
        return podcast_workflow.guided_actions_for_run(run, _PODCAST_STATE_LABELS)

    def _run_guided_action(updated_store: dict, run_id: str, action_id: str) -> None:
        current_run = next((item for item in updated_store["runs"] if item["id"] == run_id), None)
        if not current_run:
            raise ValueError("Podcast run not found.")
        run_metrics = podcast_tracker.build_run_metrics(current_run)
        if action_id == "start_local_transcript":
            start_result = _podcast_proxy_start(run_id, current_run["source_path"], current_run["title"], force=True)
            if not start_result.get("accepted", True):
                raise ValueError(_podcast_user_error_text(start_result.get("message", "The local runner is already busy.")))
            podcast_tracker.transition_run(
                updated_store,
                run_id=run_id,
                actor=actor,
                state="transcribing",
                blocker="",
                note=f"Guided action: local transcription started ({start_result.get('job', {}).get('status', 'queued')}).",
            )
        elif action_id == "transcript_ready":
            if not _podcast_artifact_has_content(current_run, "transcript"):
                raise ValueError("Save the transcript artifact first.")
            podcast_tracker.transition_run(updated_store, run_id=run_id, actor=actor, state="gate1_waiting", blocker="", note="Guided action: transcript ready for Gate 1.")
        elif action_id == "approve_gate1":
            if not _podcast_gate1_ready(current_run):
                raise ValueError("Save the title and thumbnail picks before approving Gate 1.")
            podcast_tracker.record_approval(updated_store, run_id=run_id, gate="gate1", decision="approved", actor=actor, notes="Guided action: Gate 1 approved.", state_after="gate1_approved")
        elif action_id == "gate1_changes":
            podcast_tracker.record_approval(updated_store, run_id=run_id, gate="gate1", decision="changes_requested", actor=actor, notes="Guided action: Gate 1 needs changes.", state_after="gate1_waiting")
        elif action_id == "metadata_ready":
            if not _podcast_packaging_ready(current_run):
                raise ValueError("Finish every required packaging item first.")
            podcast_tracker.transition_run(updated_store, run_id=run_id, actor=actor, state="metadata_ready", blocker="", note="Guided action: packaging is ready.")
        elif action_id == "tweet_waiting":
            podcast_tracker.transition_run(updated_store, run_id=run_id, actor=actor, state="tweet_waiting", blocker="Waiting on approved tweet.", note="Guided action: waiting on tweet.")
        elif action_id == "thumbnail_waiting":
            podcast_tracker.transition_run(updated_store, run_id=run_id, actor=actor, state="thumbnail_waiting", blocker="Waiting on approved thumbnail.", note="Guided action: waiting on thumbnail.")
        elif action_id == "tweet_ready":
            podcast_tracker.transition_run(updated_store, run_id=run_id, actor=actor, state="metadata_ready", blocker="", note="Guided action: tweet blocker cleared.")
        elif action_id == "thumbnail_ready":
            podcast_tracker.transition_run(updated_store, run_id=run_id, actor=actor, state="metadata_ready", blocker="", note="Guided action: thumbnail blocker cleared.")
        elif action_id == "start_gate2":
            if not _podcast_packaging_ready(current_run):
                raise ValueError("Finish every required packaging item first.")
            podcast_tracker.transition_run(updated_store, run_id=run_id, actor=actor, state="gate2_waiting", blocker="", note="Guided action: Gate 2 review started.")
        elif action_id == "approve_gate2":
            if not _podcast_gate2_ready(current_run):
                raise ValueError("Finish the clip review step before approving Gate 2.")
            podcast_tracker.record_approval(updated_store, run_id=run_id, gate="gate2", decision="approved", actor=actor, notes="Guided action: Gate 2 approved.", state_after="gate2_approved")
        elif action_id == "gate2_changes":
            podcast_tracker.record_approval(updated_store, run_id=run_id, gate="gate2", decision="changes_requested", actor=actor, notes="Guided action: Gate 2 sent back to packaging.", state_after="metadata_ready")
        elif action_id == "mark_ready_to_publish":
            podcast_tracker.transition_run(updated_store, run_id=run_id, actor=actor, state="ready_to_publish", blocker="", note="Guided action: ready to publish.")
        elif action_id == "start_publish":
            podcast_tracker.transition_run(updated_store, run_id=run_id, actor=actor, state="publish_pending", blocker="", note="Guided action: publish started.")
        elif action_id == "mark_retry":
            podcast_tracker.transition_run(updated_store, run_id=run_id, actor=actor, state="release_retry", blocker="Publish issue needs retry.", note="Guided action: release retry needed.")
        elif action_id == "retry_running":
            podcast_tracker.transition_run(updated_store, run_id=run_id, actor=actor, state="publish_pending", blocker="", note="Guided action: publish retry running.")
        elif action_id == "mark_public_verified":
            if run_metrics["verified_checks"] != run_metrics["verification_total"] or not _podcast_has_delivery_receipt(current_run):
                raise ValueError("Complete every verification check and save at least one delivery receipt first.")
            podcast_tracker.transition_run(updated_store, run_id=run_id, actor=actor, state="public_verified", blocker="", note="Guided action: public checks passed.")
        elif action_id == "mark_done":
            if run_metrics["verified_checks"] != run_metrics["verification_total"]:
                raise ValueError("Finish verification before marking the run done.")
            if run_metrics["requires_sync"] and run_metrics["sync_status"] != "fresh":
                raise ValueError("Record a fresh Discord sync checkpoint before marking the run done.")
            podcast_tracker.transition_run(updated_store, run_id=run_id, actor=actor, state="done", blocker="", note="Guided action: run marked done.")
        elif action_id == "restart_transcript_step":
            start_result = _podcast_proxy_start(run_id, current_run["source_path"], current_run["title"], force=True)
            if not start_result.get("accepted", True):
                raise ValueError(_podcast_user_error_text(start_result.get("message", "The local runner is already busy.")))
            podcast_tracker.transition_run(
                updated_store,
                run_id=run_id,
                actor=actor,
                state="transcribing",
                blocker="",
                note="Guided action: transcript step restarted after a blocker.",
            )
        elif action_id == "restart_clip_step":
            clip_result = _podcast_proxy_generate_clips(run_id, force=True)
            if not clip_result.get("accepted", True):
                raise ValueError(_podcast_user_error_text(clip_result.get("message", "Clip generation is already running.")))
            podcast_tracker.transition_run(
                updated_store,
                run_id=run_id,
                actor=actor,
                state="gate2_waiting",
                blocker="",
                note="Guided action: clip step restarted after a blocker.",
            )
        elif action_id == "resume_previous_state":
            resume_run = next((item for item in updated_store["runs"] if item["id"] == run_id), None)
            resume_state = (resume_run or {}).get("blocked_from_state", "") or "gate1_waiting"
            podcast_tracker.transition_run(updated_store, run_id=run_id, actor=actor, state=resume_state, blocker="", note="Guided action: returning to the exact pre-block state.")
        elif action_id == "resume_publish_retry":
            podcast_tracker.transition_run(updated_store, run_id=run_id, actor=actor, state="release_retry", blocker="", note="Guided action: manual fix cleared, returning to publish retry.")
        elif action_id == "resume_packaging":
            podcast_tracker.transition_run(updated_store, run_id=run_id, actor=actor, state="metadata_ready", blocker="", note="Guided action: manual fix cleared, returning to packaging.")
        elif action_id == "resume_gate2":
            podcast_tracker.transition_run(updated_store, run_id=run_id, actor=actor, state="gate2_waiting", blocker="", note="Guided action: manual fix cleared, returning to Gate 2.")
        elif action_id == "resume_gate1":
            podcast_tracker.transition_run(updated_store, run_id=run_id, actor=actor, state="gate1_waiting", blocker="", note="Guided action: manual fix cleared, returning to Gate 1.")
        elif action_id == "block_run":
            current_run = next((item for item in updated_store["runs"] if item["id"] == run_id), None)
            blocker_text = (current_run or {}).get("blocker", "").strip() or "Manual fix needed from the live Discord run."
            podcast_tracker.transition_run(updated_store, run_id=run_id, actor=actor, state="blocked_manual_fix", blocker=blocker_text, note="Guided action: manual blocker recorded.")
        elif action_id == "sync_now":
            podcast_tracker.record_sync_checkpoint(updated_store, run_id=run_id, actor=actor, note="Guided action: HQ mirror synced to Discord.")

    def _safe_manual_state_options(current_state: str) -> list[str]:
        options_map = {
            "initialized": ["initialized", "transcribing", "gate1_waiting", "blocked_manual_fix"],
            "transcribing": ["transcribing", "gate1_waiting", "blocked_manual_fix"],
            "gate1_waiting": ["gate1_waiting", "gate1_approved", "blocked_manual_fix"],
            "gate1_approved": ["gate1_approved", "metadata_ready", "tweet_waiting", "thumbnail_waiting", "blocked_manual_fix"],
            "metadata_ready": ["metadata_ready", "gate2_waiting", "blocked_manual_fix"],
            "tweet_waiting": ["tweet_waiting", "metadata_ready", "blocked_manual_fix"],
            "thumbnail_waiting": ["thumbnail_waiting", "metadata_ready", "blocked_manual_fix"],
            "gate2_waiting": ["gate2_waiting", "metadata_ready", "gate2_approved", "blocked_manual_fix"],
            "gate2_approved": ["gate2_approved", "ready_to_publish", "blocked_manual_fix"],
            "ready_to_publish": ["ready_to_publish", "publish_pending", "blocked_manual_fix"],
            "publish_pending": ["publish_pending", "release_retry", "public_verified", "blocked_manual_fix"],
            "release_retry": ["release_retry", "publish_pending", "blocked_manual_fix"],
            "public_verified": ["public_verified", "done", "blocked_manual_fix"],
            "done": ["done", "public_verified"],
            "blocked_manual_fix": ["blocked_manual_fix", "gate1_waiting", "metadata_ready", "gate2_waiting", "release_retry"],
        }
        options = options_map.get(current_state, [current_state, "blocked_manual_fix"])
        seen = []
        for state_id in options:
            if state_id not in seen:
                seen.append(state_id)
        return seen

    def _podcast_clean_display_value(value: str) -> str:
        return str(value or "").strip().strip("\"'")

    def _podcast_parse_numbered_options(text: str) -> list[str]:
        options = []
        for raw_line in str(text or "").splitlines():
            line = raw_line.strip()
            if not line:
                continue
            line = re.sub(r"^\d+\.\s*", "", line)
            if line:
                options.append(line)
        return options

    def _podcast_is_local_source_path(value: str) -> bool:
        return podcast_workflow.is_local_source_path(_podcast_clean_display_value(value))

    def _podcast_run_mode(run_data: dict) -> str:
        return podcast_workflow.run_mode(run_data)

    def _podcast_compact_text(value: str, limit: int = 180) -> str:
        clean = " ".join(str(value or "").split())
        if len(clean) <= limit:
            return clean
        return clean[: max(0, limit - 1)].rstrip() + "…"

    def _podcast_clip_duration_label(seconds_value: float) -> str:
        total = max(0, int(round(float(seconds_value or 0.0))))
        minutes, seconds = divmod(total, 60)
        return f"{minutes}:{seconds:02d}" if total else "Unknown length"

    def _podcast_filtered_clip_files(raw_clip_files: list[dict] | None, cached_clip_files: list[dict] | None = None) -> list[dict]:
        return podcast_sync.filtered_clip_files(raw_clip_files, cached_clip_files)

    def _podcast_recommended_clip_name(clip_files: list[dict]) -> str:
        if not clip_files:
            return ""
        def _score(item: dict) -> tuple[float, float, int]:
            duration = float(item.get("duration_seconds", 0.0) or 0.0)
            duration_score = -abs(duration - 45.0)
            return (
                10.0 if item.get("is_final") else 0.0,
                duration_score,
                int(item.get("size_bytes", 0) or 0),
            )
        return max(clip_files, key=_score).get("name", "")

    def _podcast_clip_picker_label(item: dict, idx: int, recommended_name: str) -> str:
        clip_name = str(item.get("name", f"Clip {idx + 1}")).strip()
        duration_label = _podcast_clip_duration_label(float(item.get("duration_seconds", 0.0) or 0.0))
        suffix = " · Recommended" if clip_name == recommended_name else ""
        return f"Clip {idx + 1} · {duration_label}{suffix}"

    def _podcast_progress_steps(run: dict, proxy_job: dict) -> tuple[list[dict], int]:
        return podcast_workflow.progress_steps(run, proxy_job)

    st.markdown('<div class="main-header">PODCAST <span>WORKFLOW</span></div>', unsafe_allow_html=True)
    st.markdown(
        '<div class="tool-desc">The Podcast wizard now drives the run one step at a time. The manual workspace is still here, but it stays hidden until you explicitly open it.</div>',
        unsafe_allow_html=True,
    )
    persist_status = st.session_state.get("_podcast_runs_persist_status", {"source": "local", "error": ""})
    if persist_status.get("error"):
        st.warning(persist_status["error"])
    else:
        st.caption(f"Podcast HQ persistence: {persist_status.get('source', 'local')}. Live source of truth depends on the run you have open.")
    flash_message = st.session_state.pop("_podcast_flash_message", "")
    if isinstance(flash_message, dict):
        flash_level = flash_message.get("level", "success")
        flash_text = flash_message.get("text", "")
    else:
        flash_level = "success"
        flash_text = flash_message
    if flash_text:
        if flash_level == "error":
            st.error(flash_text)
        elif flash_level == "warning":
            st.warning(flash_text)
        else:
            st.success(flash_text)
    with st.expander("Troubleshooting", expanded=False):
        st.caption("Only use these if the cloud copy looks stale or persistence fell back to local backup.")
        if st.button("Refresh Cloud", key="podcast_refresh_cloud", type="secondary", use_container_width=True):
            for key in (
                "_podcast_runs_cache",
                "_podcast_runs_cache_handle",
                "_podcast_runs_cache_loaded_at",
                "_podcast_runs_remote_cache",
                "_podcast_runs_remote_cache_handle",
                "_podcast_runs_remote_cache_loaded_at",
            ):
                st.session_state.pop(key, None)
            st.rerun()

    runs = store["runs"]
    run_lookup = {run["id"]: run for run in runs}
    proxy_job_cache: dict[str, tuple[dict, str]] = {}
    local_run_ids = [
        str(run["id"]).strip()
        for run in runs
        if _podcast_run_mode(run) == "local" and _podcast_is_local_source_path(run.get("source_path", ""))
    ]
    proxy_sync_status: dict = {}
    proxy_sync_error = ""

    if local_run_ids:
        try:
            batch_jobs = (_podcast_proxy_status_batch(local_run_ids) or {}).get("jobs", {})
            for run_id, job in batch_jobs.items():
                proxy_job_cache[str(run_id).strip()] = (job or {}, "")
        except Exception:
            pass
        try:
            proxy_sync_status = (_podcast_proxy_reconcile_status() or {}).get("sync", {})
        except Exception as exc:
            proxy_sync_error = str(exc)

    def _podcast_proxy_job_cached(run_data: dict) -> tuple[dict, str]:
        run_id = str(run_data.get("id", "")).strip()
        if not run_id:
            return {}, ""
        if run_id in proxy_job_cache:
            return proxy_job_cache[run_id]
        if _podcast_run_mode(run_data) != "local" or not _podcast_is_local_source_path(run_data.get("source_path", "")):
            proxy_job_cache[run_id] = ({}, "")
            return proxy_job_cache[run_id]
        try:
            proxy_job = (_podcast_proxy_status(run_id) or {}).get("job", {})
            proxy_job_cache[run_id] = (proxy_job, "")
        except Exception as exc:
            proxy_job_cache[run_id] = ({}, str(exc))
        return proxy_job_cache[run_id]

    def _podcast_background_sync_caption() -> str:
        if proxy_sync_error:
            return f"Background sync status is unavailable right now: {proxy_sync_error}"
        if not proxy_sync_status:
            return "Background sync is available for local runs when the proxy is online."
        last_checked = str(proxy_sync_status.get("last_checked_at", "")).strip() or "unknown"
        interval = int(proxy_sync_status.get("sleep_interval_seconds", 0) or 0)
        cadence = f"every {interval}s" if interval else "on its current cadence"
        if str(proxy_sync_status.get("last_error", "")).strip():
            return f"Background sync hit an issue after {last_checked}: {proxy_sync_status.get('last_error')}"
        if proxy_sync_status.get("running"):
            return f"Background sync is running now and checks local jobs about {cadence}."
        return f"Background sync last checked local jobs at {last_checked} and is polling about {cadence}."

    if local_run_ids:
        st.caption(_podcast_background_sync_caption())

    selected_run_id = ""
    if requested_run_id in run_lookup:
        selected_run_id = requested_run_id
    elif st.session_state.get("_podcast_last_run_id") in run_lookup:
        selected_run_id = st.session_state["_podcast_last_run_id"]
    elif store.get("active_run_id") in run_lookup:
        selected_run_id = store["active_run_id"]
    elif runs:
        selected_run_id = runs[0]["id"]
    if selected_run_id:
        st.session_state["_podcast_last_run_id"] = selected_run_id

    wizard_open_key = "_podcast_wizard_open"
    advanced_open_key = "_podcast_show_advanced"
    if wizard_open_key not in st.session_state:
        st.session_state[wizard_open_key] = True
    if advanced_open_key not in st.session_state:
        st.session_state[advanced_open_key] = False
    if "_podcast_wizard_start_new" not in st.session_state:
        st.session_state["_podcast_wizard_start_new"] = False

    @st.dialog("Podcast Workflow", width="large")
    def _podcast_workflow_wizard_dialog(dialog_nonce: str):
        st.markdown(
            '<div class="podcast-status-kicker">One Step At A Time</div><div style="font-size:22px;color:#E6EDF3;font-weight:700;line-height:1.35;margin:6px 0 10px 0;">This wizard only shows the next thing you need to do.</div>',
            unsafe_allow_html=True,
        )
        if not runs:
            _render_podcast_start_form("podcast_wizard_start_form")
            if st.button("Hide Wizard", key="podcast_hide_wizard_empty", use_container_width=True):
                st.session_state[wizard_open_key] = False
                st.rerun()
            return

        if st.session_state.get("_podcast_wizard_start_new"):
            st.info("Start a new podcast workflow here. Existing runs stay saved and can be reopened from the run selector.")
            _render_podcast_start_form("podcast_wizard_start_new_form")
            if st.button("Back To Current Run", key="podcast_wizard_back_to_current", use_container_width=True):
                st.session_state["_podcast_wizard_start_new"] = False
                st.rerun()
            return

        current_run = run_lookup.get(selected_run_id or store.get("active_run_id", "")) or runs[0]
        current_metrics = podcast_tracker.build_run_metrics(current_run)
        current_proxy_job = {}
        current_proxy_error = ""
        current_run_mode = _podcast_run_mode(current_run)
        local_source = current_run_mode == "local" and _podcast_is_local_source_path(current_run.get("source_path", ""))
        if local_source:
            current_proxy_job, current_proxy_error = _podcast_proxy_job_cached(current_run)
        clip_files = _podcast_filtered_clip_files(current_proxy_job.get("clips_files", []), current_run.get("cached_clip_files", []))
        clip_status = str(current_proxy_job.get("clips_status", "")).strip() or ("completed" if clip_files else "not_started")
        selected_clip_name = str(current_run.get("selected_clip_name", "")).strip()
        recommended_clip_name = _podcast_recommended_clip_name(clip_files)
        progress_steps, completed_steps = _podcast_progress_steps(current_run, current_proxy_job)
        progress_markup = []
        for step in progress_steps:
            chip_class = "podcast-phase-chip"
            if step["status"] == "active":
                chip_class += " is-active"
            elif step["status"] == "complete":
                chip_class += " is-complete"
            elif step["status"] == "skipped":
                chip_class += " is-skipped"
            progress_markup.append(f'<span class="{chip_class}">{html.escape(step["label"])}</span>')

        st.markdown(
            f'<div class="podcast-panel"><div class="podcast-status-kicker">Active Run</div><div style="font-size:20px;color:#E6EDF3;font-weight:700;line-height:1.3;">{html.escape(current_run["title"])}</div><div class="podcast-status-meta">{html.escape(_PODCAST_STATE_LABELS.get(current_run["current_state"], current_run["current_state"]))}</div></div>',
            unsafe_allow_html=True,
        )
        if st.button("Start A New Workflow", key=f"podcast_wizard_start_new_{current_run['id']}", type="secondary", use_container_width=True):
            st.session_state["_podcast_wizard_start_new"] = True
            st.rerun()
        st.progress(
            100 if current_run["current_state"] == "done" else max(5, int(round((completed_steps / max(1, len(progress_steps))) * 100))),
            text=f"Step {min(len(progress_steps), completed_steps + (0 if current_run['current_state'] == 'done' else 1))} of {len(progress_steps)}",
        )
        st.markdown(
            f'<div class="podcast-phase-row">{"".join(progress_markup)}</div>',
            unsafe_allow_html=True,
        )

        state = current_run["current_state"]
        if current_run.get("blocker") and state != "blocked_manual_fix":
            st.error(current_run["blocker"])

        def _save_and_stay(updated_store: dict) -> None:
            st.session_state[wizard_open_key] = True
            _save_podcast_and_rerun(updated_store, current_run["id"])

        def _open_wizard_advanced_workspace(section_name: str = "Artifacts") -> None:
            st.session_state[advanced_open_key] = True
            _set_podcast_section(current_run["id"], section_name)
            st.rerun()

        def _start_clip_generation(force: bool, success_text: str) -> None:
            try:
                clip_result = _podcast_proxy_generate_clips(current_run["id"], force=force)
                if not clip_result.get("accepted", True):
                    st.warning(_podcast_user_error_text(clip_result.get("message", "Clip generation is already running.")))
                    return
            except Exception as exc:
                st.error(_podcast_user_error_text(str(exc)))
            else:
                st.session_state["_podcast_flash_message"] = {"level": "success", "text": success_text}
                st.rerun()

        def _render_blocked_step() -> None:
            blocked_from_state = str(current_run.get("blocked_from_state", "")).strip()
            if local_source and blocked_from_state in {"initialized", "transcribing"}:
                st.info("Step 1: rerun the transcript step after the blocker is cleared.")
                if st.button("Run Transcript Step", key=f"wizard_retry_transcript_{current_run['id']}", type="primary", use_container_width=True):
                    updated_store = podcast_tracker.deepcopy_store(store)
                    try:
                        start_result = _podcast_proxy_start(current_run["id"], current_run["source_path"], current_run["title"], force=True)
                        if not start_result.get("accepted", True):
                            st.warning(_podcast_user_error_text(start_result.get("message", "The local runner is already busy.")))
                            return
                        podcast_tracker.transition_run(
                            updated_store,
                            run_id=current_run["id"],
                            actor=actor,
                            state="transcribing",
                            blocker="",
                            note="Wizard restarted the transcript step after a blocker.",
                        )
                        st.session_state["_podcast_flash_message"] = {"level": "success", "text": "Transcript step restarted."}
                        _save_and_stay(updated_store)
                    except Exception as exc:
                        st.error(_podcast_user_error_text(str(exc)))
                return

            if local_source and blocked_from_state in {"metadata_ready", "gate2_waiting"}:
                st.info("Step 4: rerun the clip step after the blocker is cleared.")
                if st.button("Run Clip Step", key=f"wizard_retry_clip_blocked_{current_run['id']}", type="primary", use_container_width=True):
                    try:
                        clip_result = _podcast_proxy_generate_clips(current_run["id"], force=True)
                        if not clip_result.get("accepted", True):
                            st.warning(_podcast_user_error_text(clip_result.get("message", "Clip generation is already running.")))
                            return
                    except Exception as exc:
                        st.error(_podcast_user_error_text(str(exc)))
                    else:
                        updated_store = podcast_tracker.deepcopy_store(store)
                        podcast_tracker.transition_run(
                            updated_store,
                            run_id=current_run["id"],
                            actor=actor,
                            state="gate2_waiting",
                            blocker="",
                            note="Wizard restarted the clip step after a blocker.",
                        )
                        st.session_state["_podcast_flash_message"] = {"level": "success", "text": "Clip step restarted."}
                        _save_and_stay(updated_store)
                return

            if blocked_from_state:
                blocked_label = _PODCAST_STATE_LABELS.get(blocked_from_state, blocked_from_state)
                st.info(f"HQ can move this run back to {blocked_label}.")
                if st.button(f"Resume {blocked_label}", key=f"wizard_resume_blocked_{current_run['id']}", type="primary", use_container_width=True):
                    updated_store = podcast_tracker.deepcopy_store(store)
                    podcast_tracker.transition_run(
                        updated_store,
                        run_id=current_run["id"],
                        actor=actor,
                        state=blocked_from_state,
                        blocker="",
                        note="Wizard resumed the blocked run.",
                    )
                    _save_and_stay(updated_store)

        def _render_initialized_step() -> None:
            if local_source:
                st.info("Step 1: start the local runner so HQ can transcribe the video.")
                if st.button("Run Transcript Step", key=f"wizard_start_runner_{current_run['id']}", type="primary", use_container_width=True):
                    updated_store = podcast_tracker.deepcopy_store(store)
                    try:
                        start_result = _podcast_proxy_start(current_run["id"], current_run["source_path"], current_run["title"], force=True)
                        if not start_result.get("accepted", True):
                            st.warning(_podcast_user_error_text(start_result.get("message", "The local runner is already busy.")))
                            return
                        podcast_tracker.transition_run(
                            updated_store,
                            run_id=current_run["id"],
                            actor=actor,
                            state="transcribing",
                            blocker="",
                            note=f"Wizard started local transcription job ({start_result.get('job', {}).get('status', 'queued')}).",
                        )
                        st.session_state["_podcast_flash_message"] = {"level": "success", "text": "Local runner started."}
                        _save_and_stay(updated_store)
                    except Exception as exc:
                        st.error(_podcast_user_error_text(str(exc)))
                return

            transcript_ready = _podcast_artifact_has_content(current_run, "transcript")
            if transcript_ready:
                st.info("Step 1: HQ already has the transcript, so you can move straight into Gate 1.")
                if st.button("Open Gate 1 Review", key=f"wizard_initialized_to_gate1_{current_run['id']}", type="primary", use_container_width=True):
                    updated_store = podcast_tracker.deepcopy_store(store)
                    podcast_tracker.transition_run(
                        updated_store,
                        run_id=current_run["id"],
                        actor=actor,
                        state="gate1_waiting",
                        blocker="",
                        note="Wizard opened Gate 1 from an already-saved transcript.",
                    )
                    _save_and_stay(updated_store)
                return

            st.info("Step 1: save the transcript first. Local file paths can run it automatically; URL and Discord mirror runs need the transcript saved manually in Advanced Workspace.")
            if st.button("Open Advanced Workspace", key=f"wizard_open_advanced_initialized_{current_run['id']}", type="primary", use_container_width=True):
                _open_wizard_advanced_workspace()

        def _render_transcribing_step() -> None:
            runner_status = str(current_proxy_job.get("status", "")).strip().title() or "Running"
            st.info(f"Step 1: the transcript step is running. Current runner status: {runner_status}.")
            st.caption("Background sync will import finished output automatically. Use Refresh View only if you want a newer snapshot right now.")
            if current_proxy_error:
                st.warning(current_proxy_error)
            if st.button("Refresh View", key=f"wizard_refresh_runner_{current_run['id']}", type="secondary", use_container_width=True):
                st.rerun()

        def _render_gate1_step() -> None:
            title_options = _podcast_parse_numbered_options(current_run["artifacts"]["title"].get("text", ""))
            thumbnail_options = _podcast_parse_numbered_options(current_run["artifacts"]["thumbnail_text"].get("text", ""))
            if not title_options or not thumbnail_options:
                st.info("Step 2: generate the Gate 1 title and thumbnail options from the transcript.")
                if st.button("Generate Gate 1 Options", key=f"wizard_generate_gate1_{current_run['id']}", type="primary", use_container_width=True):
                    updated_store = podcast_tracker.deepcopy_store(store)
                    try:
                        _podcast_generate_packaging_artifacts(updated_store, current_run)
                    except Exception as exc:
                        st.error(_podcast_user_error_text(str(exc)))
                    else:
                        st.session_state["_podcast_flash_message"] = {"level": "success", "text": "Gate 1 suggestions generated."}
                        _save_and_stay(updated_store)
                return

            title_pick_key = f"podcast_wizard_title_pick_{current_run['id']}"
            thumb_pick_key = f"podcast_wizard_thumb_pick_{current_run['id']}"
            if title_pick_key not in st.session_state or st.session_state[title_pick_key] not in title_options:
                st.session_state[title_pick_key] = title_options[0]
            if thumb_pick_key not in st.session_state or st.session_state[thumb_pick_key] not in thumbnail_options:
                st.session_state[thumb_pick_key] = thumbnail_options[0]

            st.info("Step 2: pick the title and thumbnail text you want to use, then approve Gate 1.")
            st.radio("Pick The Title", title_options, key=title_pick_key, label_visibility="collapsed")
            st.radio("Pick The Thumbnail Text", thumbnail_options, key=thumb_pick_key, label_visibility="collapsed")
            wizard_gate1_cols = st.columns(2, gap="small")
            with wizard_gate1_cols[0]:
                if st.button("Approve Gate 1 Picks", key=f"wizard_gate1_approve_{current_run['id']}", type="primary", use_container_width=True):
                    updated_store = podcast_tracker.deepcopy_store(store)
                    podcast_tracker.update_artifact(
                        updated_store,
                        run_id=current_run["id"],
                        artifact_id="title",
                        actor=actor,
                        text=st.session_state[title_pick_key],
                        path=current_run["artifacts"]["title"].get("path", ""),
                        status="approved",
                        notes="Approved in the Podcast wizard.",
                    )
                    podcast_tracker.update_artifact(
                        updated_store,
                        run_id=current_run["id"],
                        artifact_id="thumbnail_text",
                        actor=actor,
                        text=st.session_state[thumb_pick_key],
                        path=current_run["artifacts"]["thumbnail_text"].get("path", ""),
                        status="approved",
                        notes="Approved in the Podcast wizard.",
                    )
                    podcast_tracker.record_approval(
                        updated_store,
                        run_id=current_run["id"],
                        gate="gate1",
                        decision="approved",
                        actor=actor,
                        notes="Approved Gate 1 picks in the Podcast wizard.",
                        state_after="metadata_ready",
                    )
                    st.session_state["_podcast_flash_message"] = {"level": "success", "text": "Gate 1 approved. HQ moved straight into package review."}
                    _save_and_stay(updated_store)
            with wizard_gate1_cols[1]:
                if st.button("Regenerate Suggestions", key=f"wizard_gate1_regen_{current_run['id']}", use_container_width=True):
                    updated_store = podcast_tracker.deepcopy_store(store)
                    try:
                        _podcast_generate_packaging_artifacts(updated_store, current_run)
                    except Exception as exc:
                        st.error(_podcast_user_error_text(str(exc)))
                    else:
                        st.session_state["_podcast_flash_message"] = {"level": "success", "text": "Gate 1 suggestions regenerated."}
                        _save_and_stay(updated_store)

        def _render_packaging_step() -> None:
            st.info("Step 3: review the generated package, then move into clip review.")
            packaging_ready = _podcast_packaging_ready(current_run)
            missing_packaging = [
                spec["label"]
                for spec in podcast_tracker.ARTIFACT_SPECS
                if spec["id"] in _podcast_packaging_artifact_ids() and not _podcast_artifact_has_content(current_run, spec["id"])
            ]
            package_cols = st.columns(2, gap="small")
            with package_cols[0]:
                st.markdown("**Approved Title**")
                st.write(current_run["artifacts"]["title"].get("text", "") or "Not chosen yet")
                st.markdown("**Thumbnail Text**")
                st.write(current_run["artifacts"]["thumbnail_text"].get("text", "") or "Not chosen yet")
                st.markdown("**Description Preview**")
                st.caption(_podcast_compact_text(current_run["artifacts"]["description"].get("text", ""), 240) or "No description generated yet.")
            with package_cols[1]:
                st.markdown("**Episode Tweet Preview**")
                st.caption(_podcast_compact_text(current_run["artifacts"]["tweet"].get("text", ""), 220) or "No episode tweet generated yet.")
                st.markdown("**Tags Preview**")
                st.caption(_podcast_compact_text(current_run["artifacts"]["tags"].get("text", ""), 140) or "No tags generated yet.")
                st.markdown("**Clip Copy Preview**")
                st.caption(_podcast_compact_text(current_run["artifacts"]["clips"].get("text", ""), 220) or "No clip packages generated yet.")
            review_cols = st.columns(2, gap="small")
            with review_cols[0]:
                if st.button("Packaging Looks Good", key=f"wizard_start_gate2_{current_run['id']}", type="primary", use_container_width=True, disabled=not packaging_ready):
                    if not _podcast_packaging_ready(current_run):
                        st.warning("Generate or fill every required packaging item before moving on.")
                        return
                    updated_store = podcast_tracker.deepcopy_store(store)
                    podcast_tracker.transition_run(
                        updated_store,
                        run_id=current_run["id"],
                        actor=actor,
                        state="gate2_waiting",
                        blocker="",
                        note="Wizard completed package review and opened clip review.",
                    )
                    _save_and_stay(updated_store)
            with review_cols[1]:
                if st.button("Regenerate Packaging", key=f"wizard_regen_packaging_{current_run['id']}", use_container_width=True):
                    updated_store = podcast_tracker.deepcopy_store(store)
                    try:
                        _podcast_generate_packaging_artifacts(updated_store, current_run)
                    except Exception as exc:
                        st.error(_podcast_user_error_text(str(exc)))
                    else:
                        st.session_state["_podcast_flash_message"] = {"level": "success", "text": "Packaging suggestions regenerated."}
                        _save_and_stay(updated_store)
            if missing_packaging:
                st.warning(f"Missing before Gate 2: {', '.join(missing_packaging)}.")

        def _render_gate2_step() -> None:
            if not local_source:
                clip_notes_ready = _podcast_artifact_has_content(current_run, "clips")
                st.info("Step 4: this run does not use the local clip runner, so review the saved clip notes before approving Gate 2.")
                st.caption(_podcast_compact_text(current_run["artifacts"]["clips"].get("text", ""), 320) or "No clip notes are saved yet.")
                if st.button("Approve Gate 2", key=f"wizard_gate2_manual_{current_run['id']}", type="primary", use_container_width=True, disabled=not clip_notes_ready):
                    updated_store = podcast_tracker.deepcopy_store(store)
                    podcast_tracker.record_approval(
                        updated_store,
                        run_id=current_run["id"],
                        gate="gate2",
                        decision="approved",
                        actor=actor,
                        notes="Approved Gate 2 in the Podcast wizard without local clip preview.",
                        state_after="gate2_approved",
                    )
                    st.session_state["_podcast_flash_message"] = {"level": "success", "text": "Gate 2 approved."}
                    _save_and_stay(updated_store)
                if not clip_notes_ready:
                    st.warning("Save the reviewed clip notes first.")
                return

            if selected_clip_name and not clip_files:
                st.info("Step 4: HQ already has a saved clip for this run. Approve it now, or regenerate the clip step if you want fresh choices.")
                st.caption(f"Saved selected clip: {selected_clip_name}")
                fallback_cols = st.columns(2, gap="small")
                with fallback_cols[0]:
                    if st.button("Approve Saved Clip", key=f"wizard_gate2_saved_clip_{current_run['id']}", type="primary", use_container_width=True):
                        updated_store = podcast_tracker.deepcopy_store(store)
                        podcast_tracker.record_approval(
                            updated_store,
                            run_id=current_run["id"],
                            gate="gate2",
                            decision="approved",
                            actor=actor,
                            notes=f"Approved Gate 2 with saved clip {selected_clip_name}.",
                            state_after="gate2_approved",
                        )
                        st.session_state["_podcast_flash_message"] = {"level": "success", "text": f"Gate 2 approved with saved clip {selected_clip_name}."}
                        _save_and_stay(updated_store)
                with fallback_cols[1]:
                    if st.button("Run Clip Step", key=f"wizard_gate2_saved_clip_regen_{current_run['id']}", use_container_width=True):
                        _start_clip_generation(True, "Clip generation restarted.")
                return

            if clip_status in {"not_started", ""}:
                st.info("Step 4: run the clip step so you can review the real shorts options here.")
                if st.button("Run Clip Step", key=f"wizard_generate_clips_{current_run['id']}", type="primary", use_container_width=True):
                    _start_clip_generation(False, "Clip generation started.")
                return

            if clip_status in {"queued", "running"}:
                st.info("Step 4: the clip step is running.")
                st.caption("Background sync will keep reconciling local output. Use Refresh View only if you want a newer snapshot right now.")
                if st.button("Refresh View", key=f"wizard_refresh_clips_{current_run['id']}", type="secondary", use_container_width=True):
                    st.rerun()
                return

            if clip_status == "failed":
                st.error(_podcast_user_error_text(current_proxy_job.get("clips_error", "Clip generation failed.")))
                if st.button("Run Clip Step", key=f"wizard_retry_clips_{current_run['id']}", type="primary", use_container_width=True):
                    _start_clip_generation(True, "Clip generation restarted.")
                return

            if clip_files:
                clip_lookup = {item["name"]: item for item in clip_files}
                clip_names = [item["name"] for item in clip_files]
                clip_pick_key = f"podcast_clip_pick_{current_run['id']}"
                default_clip_name = selected_clip_name if selected_clip_name in clip_lookup else (recommended_clip_name or clip_names[0])
                if clip_pick_key not in st.session_state or st.session_state[clip_pick_key] not in clip_lookup:
                    st.session_state[clip_pick_key] = default_clip_name
                st.info("Step 4: review the real shorts clips and choose the one you want to use.")
                selected_clip_for_review = st.selectbox(
                    "Pick The Clip",
                    clip_names,
                    key=clip_pick_key,
                    format_func=lambda clip_name: _podcast_clip_picker_label(clip_lookup[clip_name], clip_names.index(clip_name), recommended_clip_name),
                )
                preview_clip = clip_lookup[selected_clip_for_review]
                if recommended_clip_name:
                    st.caption(f"Recommended clip: {recommended_clip_name}")
                st.caption(f"{preview_clip['name']} - {_podcast_clip_duration_label(preview_clip.get('duration_seconds', 0.0))}")
                try:
                    preview_bytes, preview_type = _podcast_proxy_fetch_clip_bytes(current_run["id"], preview_clip["name"])
                    st.video(preview_bytes, format=preview_type)
                except Exception as exc:
                    st.warning(_podcast_user_error_text(f"Could not load clip preview: {exc}"))
                clip_review_cols = st.columns(2, gap="small")
                with clip_review_cols[0]:
                    if st.button("Approve Gate 2", key=f"wizard_gate2_submit_{current_run['id']}_{preview_clip['name']}", type="primary", use_container_width=True):
                        updated_store = podcast_tracker.deepcopy_store(store)
                        podcast_tracker.select_clip(
                            updated_store,
                            run_id=current_run["id"],
                            actor=actor,
                            clip_name=preview_clip["name"],
                            clip_path=preview_clip["path"],
                        )
                        podcast_tracker.record_approval(
                            updated_store,
                            run_id=current_run["id"],
                            gate="gate2",
                            decision="approved",
                            actor=actor,
                            notes=f"Approved Gate 2 with selected clip {preview_clip['name']}.",
                            state_after="gate2_approved",
                        )
                        st.session_state["_podcast_flash_message"] = {"level": "success", "text": f"Gate 2 approved with clip {preview_clip['name']}."}
                        _save_and_stay(updated_store)
                with clip_review_cols[1]:
                    if st.button("Run Clip Step Again", key=f"wizard_regen_clips_{current_run['id']}", use_container_width=True):
                        _start_clip_generation(True, "Clip generation restarted.")
                return

            st.warning("No usable clips are available yet.")
            empty_clip_cols = st.columns(2, gap="small")
            with empty_clip_cols[0]:
                if st.button("Run Clip Step", key=f"wizard_empty_clip_retry_{current_run['id']}", type="primary", use_container_width=True):
                    _start_clip_generation(True, "Clip generation restarted.")
            with empty_clip_cols[1]:
                if st.button("Open Advanced Workspace", key=f"wizard_empty_clip_advanced_{current_run['id']}", use_container_width=True):
                    _open_wizard_advanced_workspace()

        def _render_gate2_approved_step() -> None:
            st.info("Step 5: mark this package ready to publish.")
            if st.button("Ready To Publish", key=f"wizard_mark_ready_publish_{current_run['id']}", type="primary", use_container_width=True):
                updated_store = podcast_tracker.deepcopy_store(store)
                podcast_tracker.transition_run(updated_store, run_id=current_run["id"], actor=actor, state="ready_to_publish", blocker="", note="Wizard marked the run ready to publish.")
                _save_and_stay(updated_store)

        def _render_ready_to_publish_step() -> None:
            st.info("Step 6: once the episode is live, move into the final link-and-verification check.")
            if st.button("It Is Live, Add Public Links", key=f"wizard_publish_ready_{current_run['id']}", type="primary", use_container_width=True):
                updated_store = podcast_tracker.deepcopy_store(store)
                podcast_tracker.transition_run(updated_store, run_id=current_run["id"], actor=actor, state="publish_pending", blocker="", note="Wizard moved the run into the final publish check.")
                _save_and_stay(updated_store)

        def _render_publish_pending_step() -> None:
            st.info("Step 7: save the public links, then finish verification when every check is true.")
            with st.form(f"podcast_wizard_publish_verify_{current_run['id']}"):
                wizard_youtube = st.text_input("YouTube Link", value=current_run["deliveries"]["youtube"]["url"])
                wizard_x = st.text_input("X Link", value=current_run["deliveries"]["x"]["url"])
                verify_public = st.checkbox("Public URL works", value=bool(current_run["verification"]["public_url_checked"]))
                verify_processing = st.checkbox("Processing finished", value=bool(current_run["verification"]["processing_checked"]))
                verify_transcript = st.checkbox("Transcript is available", value=bool(current_run["verification"]["transcript_checked"]))
                verify_social = st.checkbox("Social receipt is confirmed", value=bool(current_run["verification"]["social_ids_checked"]))
                publish_save_links = st.form_submit_button("Save Public Links", use_container_width=True)
                wizard_publish_submit = st.form_submit_button("Finish Workflow", type="primary", use_container_width=True)

            if publish_save_links:
                updated_store = podcast_tracker.deepcopy_store(store)
                if wizard_youtube.strip():
                    podcast_tracker.update_delivery(updated_store, run_id=current_run["id"], channel="youtube", actor=actor, status="posted", external_id="", url=wizard_youtube, notes="Saved from the Podcast wizard.")
                if wizard_x.strip():
                    podcast_tracker.update_delivery(updated_store, run_id=current_run["id"], channel="x", actor=actor, status="posted", external_id="", url=wizard_x, notes="Saved from the Podcast wizard.")
                st.session_state["_podcast_flash_message"] = {"level": "success", "text": "Public links saved."}
                _save_and_stay(updated_store)
                return

            if wizard_publish_submit:
                if not (wizard_youtube.strip() or wizard_x.strip()):
                    st.error("Add at least one public link before marking the run verified.")
                elif not all([verify_public, verify_processing, verify_transcript, verify_social]):
                    st.error("Check every verification box before marking the run verified.")
                else:
                    updated_store = podcast_tracker.deepcopy_store(store)
                    if wizard_youtube.strip():
                        podcast_tracker.update_delivery(updated_store, run_id=current_run["id"], channel="youtube", actor=actor, status="verified", external_id="", url=wizard_youtube, notes="Saved from the Podcast wizard.")
                    if wizard_x.strip():
                        podcast_tracker.update_delivery(updated_store, run_id=current_run["id"], channel="x", actor=actor, status="verified", external_id="", url=wizard_x, notes="Saved from the Podcast wizard.")
                    podcast_tracker.update_verification(
                        updated_store,
                        run_id=current_run["id"],
                        actor=actor,
                        checks={
                            "public_url_checked": verify_public,
                            "processing_checked": verify_processing,
                            "transcript_checked": verify_transcript,
                            "social_ids_checked": verify_social,
                        },
                        notes="Verified from the Podcast wizard.",
                    )
                    final_state = "public_verified" if current_metrics["requires_sync"] else "done"
                    final_note = "Wizard completed publish verification and is waiting on a Discord sync checkpoint." if current_metrics["requires_sync"] else "Wizard completed publish verification and marked the run done."
                    podcast_tracker.transition_run(updated_store, run_id=current_run["id"], actor=actor, state=final_state, blocker="", note=final_note)
                    st.session_state["_podcast_flash_message"] = {
                        "level": "success",
                        "text": "Publish links saved. HQ is done." if not current_metrics["requires_sync"] else "Publish links saved. Record the final Discord sync checkpoint next.",
                    }
                    _save_and_stay(updated_store)

        def _render_public_verified_step() -> None:
            if current_metrics["requires_sync"] and current_metrics["sync_status"] != "fresh":
                st.info("Step 8: record a fresh Discord sync checkpoint before HQ marks this run done.")
                if st.button("Mark Discord Sync Checkpoint", key=f"wizard_sync_done_{current_run['id']}", type="primary", use_container_width=True):
                    updated_store = podcast_tracker.deepcopy_store(store)
                    podcast_tracker.record_sync_checkpoint(updated_store, run_id=current_run["id"], actor=actor, note="Wizard recorded a final Discord sync checkpoint.")
                    _save_and_stay(updated_store)
                return

            st.success("Step 8: everything is verified. Mark the run done.")
            if st.button("Mark Done", key=f"wizard_done_{current_run['id']}", type="primary", use_container_width=True):
                updated_store = podcast_tracker.deepcopy_store(store)
                podcast_tracker.transition_run(updated_store, run_id=current_run["id"], actor=actor, state="done", blocker="", note="Wizard marked the run done.")
                _save_and_stay(updated_store)

        def _render_done_step() -> None:
            st.success("This run is done.")
            if st.button("Hide Wizard", key=f"wizard_hide_{current_run['id']}_done", type="primary", use_container_width=True):
                st.session_state[wizard_open_key] = False
                st.rerun()

        def _render_fallback_step() -> None:
            fallback_actions = _guided_actions_for_run(current_run)
            if fallback_actions:
                next_action = fallback_actions[0]
                st.info(next_action["help"])
                if st.button(next_action["label"], key=f"wizard_fallback_{current_run['id']}_{next_action['id']}", type="primary", use_container_width=True, disabled=next_action.get("disabled", False)):
                    updated_store = podcast_tracker.deepcopy_store(store)
                    try:
                        _run_guided_action(updated_store, current_run["id"], next_action["id"])
                    except Exception as exc:
                        st.error(_podcast_user_error_text(str(exc)))
                    else:
                        _save_and_stay(updated_store)
            if st.button("Hide Wizard", key=f"wizard_hide_{current_run['id']}_fallback", use_container_width=True):
                st.session_state[wizard_open_key] = False
                st.rerun()

        if state == "blocked_manual_fix":
            _render_blocked_step()
            return

        if state == "initialized":
            _render_initialized_step()
            return

        if state == "transcribing" or str(current_proxy_job.get("status", "")).strip() in {"queued", "running"}:
            _render_transcribing_step()
            return

        wizard_state_renderers = {
            "gate1_waiting": _render_gate1_step,
            "gate1_approved": _render_packaging_step,
            "metadata_ready": _render_packaging_step,
            "gate2_waiting": _render_gate2_step,
            "gate2_approved": _render_gate2_approved_step,
            "ready_to_publish": _render_ready_to_publish_step,
            "publish_pending": _render_publish_pending_step,
            "public_verified": _render_public_verified_step,
            "done": _render_done_step,
        }
        render_step = wizard_state_renderers.get(state)
        if render_step:
            render_step()
            return

        _render_fallback_step()

    if st.session_state.get(wizard_open_key):
        _podcast_workflow_wizard_dialog(f"{selected_run_id}:{store.get('updated_at', '')}:{len(runs)}")

    toolbar_cols = st.columns([1.1, 1.1, 1.1, 1.6], gap="small")
    with toolbar_cols[0]:
        if st.button("Reopen Wizard" if not st.session_state.get(wizard_open_key) else "Wizard Open", key="podcast_open_wizard_toolbar", type="primary", use_container_width=True, disabled=st.session_state.get(wizard_open_key)):
            st.session_state[wizard_open_key] = True
            st.rerun()
    with toolbar_cols[1]:
        if st.button("Start New Workflow", key="podcast_start_new_toolbar", type="secondary", use_container_width=True):
            st.session_state["_podcast_wizard_start_new"] = True
            st.session_state[wizard_open_key] = True
            st.rerun()
    with toolbar_cols[2]:
        if st.button("Open Advanced Workspace" if not st.session_state.get(advanced_open_key) else "Hide Advanced Workspace", key="podcast_toggle_advanced_toolbar", type="secondary", use_container_width=True):
            st.session_state[advanced_open_key] = not st.session_state.get(advanced_open_key)
            st.rerun()
    with toolbar_cols[3]:
        if runs:
            current_label = _podcast_run_label(run_lookup[selected_run_id])
            st.caption(f"Current run: {current_label}")
        else:
            st.caption("No run yet. Use the wizard to start one.")

    if not st.session_state.get(advanced_open_key):
        if not runs:
            st.info("The wizard is the only thing you need here. It will walk you through the run one step at a time.")
            return
        compact_run = run_lookup[selected_run_id]
        compact_proxy_job, _ = _podcast_proxy_job_cached(compact_run)
        compact_steps, compact_completed = _podcast_progress_steps(compact_run, compact_proxy_job)
        compact_step_markup = []
        for step in compact_steps:
            chip_class = "podcast-phase-chip"
            if step["status"] == "active":
                chip_class += " is-active"
            elif step["status"] == "complete":
                chip_class += " is-complete"
            elif step["status"] == "skipped":
                chip_class += " is-skipped"
            compact_step_markup.append(f'<span class="{chip_class}">{html.escape(step["label"])}</span>')
        st.markdown(
            f"""
            <div class="podcast-panel">
              <div class="podcast-status-kicker">Wizard Mode</div>
              <div style="font-size:20px;color:#E6EDF3;font-weight:700;line-height:1.35;">{html.escape(compact_run['title'])}</div>
              <div class="podcast-status-meta">{html.escape(_PODCAST_STATE_LABELS.get(compact_run['current_state'], compact_run['current_state']))}. Keep the popup open and use only the next button it shows you.</div>
              <div class="podcast-phase-row">{"".join(compact_step_markup)}</div>
            </div>
            """,
            unsafe_allow_html=True,
        )
        st.progress(
            100 if compact_run["current_state"] == "done" else max(5, int(round((compact_completed / max(1, len(compact_steps))) * 100))),
            text=f"Step {min(len(compact_steps), compact_completed + (0 if compact_run['current_state'] == 'done' else 1))} of {len(compact_steps)}",
        )
        return

    if not runs:
        dashboard = get_podcast_dashboard_content(requested_state or None)
        empty_cards = [
            _podcast_card_html("Start Path", "HQ Or Discord", "Paste a video link above for the fastest HQ-first start, or attach a Discord thread for side-by-side tracking."),
            _podcast_card_html("HQ Mode", "Ready", "Paste a video link above to start tracking artifacts, approvals, deliveries, and verification."),
            _podcast_card_html("Mirror State", dashboard["current_state_label"], "This preview only shows the modeled workflow until a real HQ run exists."),
        ]
        st.caption("No podcast runs yet. Paste a video link above to start in HQ with the fewest clicks, then add a Discord thread if you want side-by-side tracking.")
        st.markdown(f'<div class="podcast-status-grid">{"".join(empty_cards)}</div>', unsafe_allow_html=True)

        phase_chips = []
        for phase in dashboard["phases"]:
            chip_class = "podcast-phase-chip"
            if phase["status"] == "active":
                chip_class += " is-active"
            elif phase["status"] == "complete":
                chip_class += " is-complete"
            elif phase["status"] == "skipped":
                chip_class += " is-skipped"
            phase_chips.append(f'<span class="{chip_class}">{html.escape(phase["label"])}</span>')

        next_action_items = "".join(f"<li>{html.escape(item)}</li>" for item in dashboard["next_actions"])
        st.markdown(
            f"""
            <div class="podcast-panel">
              <div class="podcast-status-kicker">Workflow Preview</div>
              <div style="font-size:18px;color:#E6EDF3;font-weight:700;line-height:1.4;">HQ becomes the durable control board. Discord can stay live beside it when needed.</div>
              <div class="podcast-phase-row">{"".join(phase_chips)}</div>
              <ul style="margin:0 0 0 18px;color:#C9D1D9;line-height:1.8;font-size:13px;padding:0;">{next_action_items}</ul>
            </div>
            """,
            unsafe_allow_html=True,
        )
        return

    if selected_run_id and st.query_params.get("podcast_run") != selected_run_id:
        st.query_params["podcast_run"] = selected_run_id

    selector_col, mirror_col = st.columns([1.6, 1], gap="large")
    with selector_col:
        run_ids = [run["id"] for run in runs]
        selected_from_ui = st.selectbox(
            "Active HQ Run",
            run_ids,
            index=run_ids.index(selected_run_id),
            format_func=lambda run_id: _podcast_run_label(run_lookup[run_id]),
            help="Choose which podcast run you want to operate on.",
        )
        preview_metrics = podcast_tracker.build_run_metrics(run_lookup[selected_from_ui])
    with mirror_col:
        st.markdown(
            (
                '<div class="podcast-panel"><div class="podcast-status-kicker">Current Mode</div><div style="font-size:18px;color:#E6EDF3;font-weight:700;line-height:1.4;">Discord is still the live path.</div><div class="podcast-status-meta">Every button here updates HQ tracking only so you can pressure-test the new workflow without disrupting Booth.</div></div>'
                if preview_metrics["requires_sync"]
                else '<div class="podcast-panel"><div class="podcast-status-kicker">Current Mode</div><div style="font-size:18px;color:#E6EDF3;font-weight:700;line-height:1.4;">HQ started this run first.</div><div class="podcast-status-meta">Use the guided buttons here as your working record. Add a Discord thread later if you want side-by-side validation.</div></div>'
            ),
            unsafe_allow_html=True,
        )
    if selected_from_ui != selected_run_id:
        st.query_params["podcast_run"] = selected_from_ui
        st.query_params["podcast_state"] = run_lookup[selected_from_ui]["current_state"]
        st.rerun()

    run = run_lookup[selected_run_id]
    proxy_job, proxy_job_error = _podcast_proxy_job_cached(run)
    dashboard = get_podcast_dashboard_content(run["current_state"])
    metrics = podcast_tracker.build_run_metrics(run)
    latest_gate_decisions = metrics["latest_gate_decisions"]
    if st.query_params.get("podcast_state") != run["current_state"]:
        st.query_params["podcast_state"] = run["current_state"]

    selected_clip_label = metrics.get("selected_clip_name") or "Not selected yet"
    runner_status = str(proxy_job.get("status", "")).strip().title() if proxy_job else "Not started"
    clips_status = str(proxy_job.get("clips_status", "")).strip().replace("_", " ").title() if proxy_job else "Not started"
    minimal_cards = [
        _podcast_card_html("Current Step", dashboard["current_state_label"], "The wizard will keep showing only the next thing to do."),
        _podcast_card_html("Runner", runner_status or "Unknown", "This is the independent local HQ runner."),
        _podcast_card_html("Shorts Clips", clips_status or "Not started", f"Selected clip: {selected_clip_label}"),
    ]
    st.markdown(f'<div class="podcast-status-grid">{"".join(minimal_cards)}</div>', unsafe_allow_html=True)
    if run.get("blocker"):
        st.error(f"Current blocker: {run.get('blocker')}")
    if not st.session_state.get(advanced_open_key):
        return

    primary_path_value = "Discord" if metrics["requires_sync"] else "HQ Start"
    primary_path_meta = (
        "Booth and the current unpublished workflow remain untouched while HQ tracks the run."
        if metrics["requires_sync"]
        else "This run started in HQ first. Add a Discord thread later if you want side-by-side sync checks."
    )
    sync_label = "Discord Sync" if metrics["requires_sync"] else "Sync Mode"
    sync_meta = (
        f"Last synced at {run.get('last_synced_at') or 'Never'} from the Discord workflow."
        if metrics["requires_sync"]
        else "Discord sync is optional until you attach a Discord thread to this run."
    )
    summary_cards = [
        _podcast_card_html("Primary Live Path", primary_path_value, primary_path_meta),
        _podcast_card_html("Current State", dashboard["current_state_label"], f"Last changed at {run['state_updated_at'] or run['updated_at'] or run['created_at']}."),
        _podcast_card_html(
            sync_label,
            metrics["sync_status"].replace("_", " ").title(),
            sync_meta,
        ),
        _podcast_card_html("Artifacts", f"{metrics['artifact_approved']}/{metrics['artifact_total']}", f"{metrics['artifact_populated']} populated, {metrics['artifact_blocked']} blocked."),
        _podcast_card_html(
            "Approvals",
            f"{sum(1 for decision in latest_gate_decisions.values() if decision and decision['decision'] == 'approved')}/{len(podcast_tracker.APPROVAL_GATES)}",
            "Gate approvals are now explicit HQ records instead of scattered chat context.",
        ),
        _podcast_card_html(
            "Verification",
            f"{metrics['verified_checks']}/{metrics['verification_total']}",
            "Done only means done after public checks and social receipts are recorded.",
        ),
    ]
    if local_run_ids:
        sync_summary = "Healthy" if not proxy_sync_error and not str(proxy_sync_status.get("last_error", "")).strip() else "Needs attention"
        sync_meta = _podcast_background_sync_caption()
        summary_cards.append(_podcast_card_html("Background Sync", sync_summary, sync_meta))
    st.markdown(f'<div class="podcast-status-grid">{"".join(summary_cards)}</div>', unsafe_allow_html=True)
    if proxy_job:
        proxy_status = str(proxy_job.get("status", "")).strip().title() or "Unknown"
        proxy_meta = str(proxy_job.get("error", "")).strip() or f"Updated at {proxy_job.get('updated_at') or 'Unknown'}."
        st.markdown(
            f'<div class="podcast-panel"><div class="podcast-status-kicker">Local Runner</div><div style="font-size:18px;color:#E6EDF3;font-weight:700;line-height:1.35;">{html.escape(proxy_status)}</div><div class="podcast-status-meta">{html.escape(proxy_meta)}</div></div>',
            unsafe_allow_html=True,
        )
        runner_cols = st.columns([1, 1.4], gap="small")
        with runner_cols[0]:
            if st.button("Refresh View", key=f"podcast_refresh_runner_{run['id']}", type="secondary", use_container_width=True):
                st.rerun()
        with runner_cols[1]:
            if proxy_job.get("output_dir"):
                st.caption(f"Local output directory: {proxy_job.get('output_dir')}")
    elif _podcast_run_mode(run) == "local" and not metrics["requires_sync"] and _podcast_is_local_source_path(run.get("source_path", "")):
        st.info("This HQ run has a local source path but no local runner job yet.")
        if st.button("Start Local Runner", key=f"podcast_start_runner_{run['id']}", type="primary", use_container_width=True):
            updated_store = podcast_tracker.deepcopy_store(store)
            try:
                start_result = _podcast_proxy_start(run["id"], run["source_path"], run["title"], force=True)
                if run["current_state"] in {"initialized", "blocked_manual_fix"}:
                    podcast_tracker.transition_run(
                        updated_store,
                        run_id=run["id"],
                        actor=actor,
                        state="transcribing",
                        blocker="",
                        note=f"Independent HQ runner started local transcription job ({start_result.get('job', {}).get('status', 'queued')}).",
                    )
                st.session_state["_podcast_flash_message"] = {"level": "success", "text": "Local podcast runner started on your proxy host."}
                _save_podcast_and_rerun(updated_store, run["id"])
            except Exception as exc:
                podcast_tracker.transition_run(
                    updated_store,
                    run_id=run["id"],
                    actor=actor,
                    state="blocked_manual_fix",
                    blocker=f"Local podcast start failed: {exc}",
                    note="Independent HQ runner failed to start on the proxy host.",
                )
                st.session_state["_podcast_flash_message"] = {"level": "error", "text": f"Local podcast start failed: {exc}"}
                _save_podcast_and_rerun(updated_store, run["id"])
    elif proxy_job_error and not metrics["requires_sync"]:
        st.warning(f"Local runner status is unavailable right now: {proxy_job_error}")
    if run["current_state"] == "blocked_manual_fix" or run.get("blocker"):
        st.error(f"Current blocker: {run.get('blocker') or 'Manual fix is required before HQ should move forward.'}")
    if not run["artifacts"]["clips"]["path"]:
        st.info("Shorts output is not set yet. Open Artifacts > Shorts Clips and save the real folder or URL where the live workflow wrote the clips.")

    guided_actions = _guided_actions_for_run(run)
    st.markdown(
        f"""
        <div class="podcast-panel">
          <div class="podcast-status-kicker">Simple Operator Flow</div>
          <div style="font-size:20px;color:#E6EDF3;font-weight:700;line-height:1.35;margin-bottom:8px;">Press the next obvious button here.</div>
          <div class="podcast-status-meta">{'1. Keep Booth running in Discord. 2. When something finishes there, click the matching button below in HQ. 3. Only use the detailed editors further down if something unusual happens.' if metrics['requires_sync'] else '1. This run started in HQ. 2. Use the guided buttons below as each step finishes. 3. Add a Discord thread later only if you want side-by-side validation.'}</div>
        </div>
        """,
        unsafe_allow_html=True,
    )
    if metrics["requires_sync"] and metrics["sync_status"] in {"unsynced", "aging", "stale"}:
        if st.button("Go To Sync Checkpoint", key=f"podcast_sync_prompt_{run['id']}", type="primary", use_container_width=True):
            _set_podcast_section(run["id"], "Activity")
            st.rerun()
    if guided_actions:
        disabled_actions = [action["help"] for action in guided_actions if action.get("disabled")]
        if disabled_actions:
            st.info(f"Unlock the next step: {disabled_actions[0]}")
        guided_cols = st.columns(min(3, len(guided_actions)), gap="small")
        for idx, action in enumerate(guided_actions):
            with guided_cols[idx % len(guided_cols)]:
                if st.button(
                    action["label"],
                    key=f"podcast_guided_{run['id']}_{action['id']}",
                    type=action["type"],
                    use_container_width=True,
                    disabled=action.get("disabled", False),
                ):
                    updated_store = podcast_tracker.deepcopy_store(store)
                    _set_podcast_section(run["id"], action["section"])
                    try:
                        _run_guided_action(updated_store, run["id"], action["id"])
                    except Exception as exc:
                        st.error(_podcast_user_error_text(str(exc)))
                    else:
                        _save_podcast_and_rerun(updated_store, run["id"])
                st.caption(action["help"])

    st.caption("Need something specific? Jump straight to the right editor below.")
    section_labels = ["Overview", "Artifacts", "Approvals", "Delivery & Verify", "Activity"]
    section_cols = st.columns(len(section_labels), gap="small")
    for idx, section_name in enumerate(section_labels):
        with section_cols[idx]:
            if st.button(
                section_name,
                key=f"podcast_jump_{run['id']}_{section_name}",
                use_container_width=True,
                type="primary" if st.session_state.get(f"podcast_section_{run['id']}", "Overview") == section_name else "secondary",
            ):
                _set_podcast_section(run["id"], section_name)
                st.rerun()

    hero_col, detail_col = st.columns([1.6, 1], gap="large")
    with hero_col:
        source_truth_label = "Discord" if metrics["requires_sync"] else "HQ"
        st.markdown(
            f"""
            <div class="podcast-panel">
              <div class="podcast-status-kicker">Active Podcast Run</div>
              <div style="font-size:24px;color:#E6EDF3;font-weight:700;line-height:1.35;margin-bottom:10px;">{html.escape(run['title'])}</div>
              <div class="podcast-inline-kv"><span>Episode Code</span><strong>{html.escape(run['episode_code'] or 'Not Set')}</strong></div>
              <div class="podcast-inline-kv"><span>Source</span><strong>{_podcast_value_html(run['source_path'], link_label='Open Source Link')}</strong></div>
              <div class="podcast-inline-kv"><span>Discord Ref</span><strong>{_podcast_value_html(run['discord_reference'], link_label='Open Discord Thread')}</strong></div>
              <div class="podcast-inline-kv"><span>Shorts Output</span><strong>{_podcast_value_html(run['artifacts']['clips']['path'], empty_label='Set this in Artifacts > Shorts Clips', link_label='Open Clips Output')}</strong></div>
              <div class="podcast-inline-kv"><span>Source of Truth</span><strong>{html.escape(source_truth_label)}</strong></div>
              <div class="podcast-inline-kv"><span>Last Synced</span><strong>{html.escape(run.get('last_synced_at') or 'Never')}</strong></div>
              <div class="podcast-inline-kv"><span>Publish Window</span><strong>{html.escape(run['publish_window'] or 'Not Set')}</strong></div>
              <div class="podcast-inline-kv"><span>Current Blocker</span><strong>{html.escape(run['blocker'] or 'None')}</strong></div>
            </div>
            """,
            unsafe_allow_html=True,
        )
    with detail_col:
        last_event = metrics["last_event"]
        st.markdown(
            f"""
            <div class="podcast-panel">
              <div class="podcast-status-kicker">Run Snapshot</div>
              <div style="font-size:18px;color:#E6EDF3;font-weight:700;line-height:1.4;">HQ now has durable memory for this run.</div>
              <div class="podcast-status-meta" style="margin-top:10px;">Created: {html.escape(run['created_at'] or 'Unknown')}</div>
              <div class="podcast-status-meta">Updated: {html.escape(run['updated_at'] or 'Unknown')}</div>
              <div class="podcast-status-meta">Notes: {html.escape(run['notes'] or 'None yet')}</div>
              <div class="podcast-status-meta" style="margin-top:10px;">Latest event: {html.escape((last_event or {}).get('summary', 'No events yet'))}</div>
            </div>
            """,
            unsafe_allow_html=True,
        )

    section_key = f"podcast_section_{run['id']}"
    if section_key not in st.session_state:
        st.session_state[section_key] = "Overview"
    active_section = st.session_state[section_key]
    st.caption(f"Detailed editor: {active_section}. Use the jump buttons above when you need a different section.")

    if active_section == "Overview":
        details_col, transition_col = st.columns(2, gap="large")
        with details_col:
            st.markdown('<div class="podcast-status-kicker">Run Details</div>', unsafe_allow_html=True)
            with st.form(f"podcast_details_form_{run['id']}"):
                details_title = st.text_input("Run Title", value=run["title"])
                details_episode_code = st.text_input("Episode Code", value=run["episode_code"])
                details_source = st.text_input("Source File / Link", value=run["source_path"])
                details_discord = st.text_input("Discord Reference", value=run["discord_reference"])
                details_window = st.text_input("Publish Window", value=run["publish_window"])
                details_notes = st.text_area("Run Notes", value=run["notes"], height=140)
                details_submitted = st.form_submit_button("Save Run Details", type="primary", use_container_width=True)
            if details_submitted:
                updated_store = podcast_tracker.deepcopy_store(store)
                podcast_tracker.update_run_details(
                    updated_store,
                    run_id=run["id"],
                    actor=actor,
                    title=details_title,
                    episode_code=details_episode_code,
                    source_path=details_source,
                    discord_reference=details_discord,
                    publish_window=details_window,
                    blocker=run["blocker"],
                    notes=details_notes,
                )
                _save_podcast_and_rerun(updated_store, run["id"])
        with transition_col:
            with st.expander("Advanced correction only", expanded=False):
                st.caption("Use this only for unusual rewinds, corrections, or manual-fix handling. The guided buttons above are safer for normal mirroring.")
                safe_state_ids = _safe_manual_state_options(run["current_state"])
                state_labels = {option["id"]: option["label"] for option in dashboard["state_options"]}
                with st.form(f"podcast_state_form_{run['id']}"):
                    next_state = st.selectbox(
                        "Safe Manual State",
                        safe_state_ids,
                        index=safe_state_ids.index(run["current_state"]) if run["current_state"] in safe_state_ids else 0,
                        format_func=lambda state_id: state_labels.get(state_id, state_id),
                        help="This is a safety-limited manual state editor. Use the guided buttons above for normal workflow updates.",
                    )
                    blocker_value = st.text_input(
                        "Set New Blocker (Optional)",
                        value=run["blocker"] if run["current_state"] == "blocked_manual_fix" else "",
                        placeholder="Leave blank to keep the current blocker.",
                        help="Blockers only change if you type a new value or explicitly clear them below.",
                    )
                    clear_blocker = st.checkbox("Clear blocker on save")
                    transition_note = st.text_area("Why are you changing the state?", height=120, placeholder="Use this only for unusual corrections or rewinds.")
                    transition_submitted = st.form_submit_button("Save Manual State Change", type="primary", use_container_width=True)
                if transition_submitted:
                    updated_store = podcast_tracker.deepcopy_store(store)
                    next_blocker = "" if clear_blocker else (blocker_value.strip() or run["blocker"])
                    if next_state == "blocked_manual_fix" and not next_blocker.strip():
                        st.warning("Add a blocker before sending the run to Manual Fix.")
                    else:
                        podcast_tracker.transition_run(
                            updated_store,
                            run_id=run["id"],
                            actor=actor,
                            state=next_state,
                            blocker=next_blocker,
                            note=transition_note,
                        )
                        _save_podcast_and_rerun(updated_store, run["id"])

        phase_chips = []
        for phase in dashboard["phases"]:
            chip_class = "podcast-phase-chip"
            if phase["status"] == "active":
                chip_class += " is-active"
            elif phase["status"] == "complete":
                chip_class += " is-complete"
            elif phase["status"] == "skipped":
                chip_class += " is-skipped"
            phase_chips.append(f'<span class="{chip_class}">{html.escape(phase["label"])}</span>')
        next_action_items = "".join(f"<li>{html.escape(item)}</li>" for item in dashboard["next_actions"])
        workflow_col, action_col = st.columns([1.5, 1], gap="large")
        with workflow_col:
            st.markdown(
                f"""
                <div class="podcast-panel">
                  <div class="podcast-status-kicker">Workflow Phases</div>
                  <div style="font-size:18px;color:#E6EDF3;font-weight:700;line-height:1.4;">Track the real run with durable HQ state, not memory.</div>
                  <div class="podcast-phase-row">{"".join(phase_chips)}</div>
                </div>
                """,
                unsafe_allow_html=True,
            )
        with action_col:
            st.markdown(
                f"""
                <div class="podcast-panel">
                  <div class="podcast-status-kicker">Next Actions</div>
                  <ul style="margin:0 0 0 18px;color:#C9D1D9;line-height:1.75;font-size:13px;padding:0;">{next_action_items}</ul>
                </div>
                """,
                unsafe_allow_html=True,
            )

    if active_section == "Artifacts":
        artifact_lookup = {spec["id"]: spec for spec in podcast_tracker.ARTIFACT_SPECS}
        artifact_ids = [spec["id"] for spec in podcast_tracker.ARTIFACT_SPECS]
        artifact_key = f"podcast_artifact_{run['id']}"
        transcript_available = _podcast_artifact_has_content(run, "transcript")
        packaging_ready = _podcast_packaging_ready(run)
        if transcript_available:
            st.markdown(
                '<div class="podcast-panel"><div class="podcast-status-kicker">Packaging Generator</div><div style="font-size:18px;color:#E6EDF3;font-weight:700;line-height:1.35;">Generate titles, description, tags, tweets, thumbnail text, and clip ideas from the transcript.</div><div class="podcast-status-meta">This fills the packaging artifacts with draft suggestions so you do not have to paste them manually.</div></div>',
                unsafe_allow_html=True,
            )
            generator_cols = st.columns([1.2, 1.2], gap="small")
            with generator_cols[0]:
                if st.button(
                    "Generate Packaging Suggestions",
                    key=f"podcast_generate_packaging_{run['id']}",
                    type="primary",
                    use_container_width=True,
                ):
                    updated_store = podcast_tracker.deepcopy_store(store)
                    try:
                        _podcast_generate_packaging_artifacts(updated_store, run)
                    except Exception as exc:
                        st.warning(str(exc))
                    else:
                        st.session_state["_podcast_flash_message"] = {"level": "success", "text": "Packaging suggestions generated from the transcript."}
                        _save_podcast_and_rerun(updated_store, run["id"])
            with generator_cols[1]:
                status_copy = "Packaging suggestions are ready." if packaging_ready else "Packaging suggestions still need to be generated or completed."
                st.caption(status_copy)
        else:
            st.info("Transcript is required before packaging suggestions can be generated.")
        if artifact_key not in st.session_state:
            st.session_state[artifact_key] = next(
                (
                    artifact_id
                    for artifact_id in artifact_ids
                    if run["artifacts"][artifact_id]["status"] in {"blocked", "missing"}
                ),
                artifact_ids[0],
            )
        selected_artifact_id = st.session_state[artifact_key]
        artifact_card_cols = st.columns(min(3, len(artifact_ids)), gap="small")
        for idx, artifact_id in enumerate(artifact_ids):
            artifact = run["artifacts"][artifact_id]
            with artifact_card_cols[idx % len(artifact_card_cols)]:
                st.markdown(
                    (
                        '<div class="podcast-artifact-card">'
                        f'<div class="podcast-status-kicker">{html.escape(artifact_lookup[artifact_id]["label"])}</div>'
                        f'<div class="podcast-artifact-status is-{html.escape(artifact["status"])}">{html.escape(artifact["status"].replace("_", " ").title())}</div>'
                        f'<div class="podcast-status-meta">Version {artifact["version"]} · Updated {html.escape(artifact["updated_at"] or "Not yet")}</div>'
                        '</div>'
                    ),
                    unsafe_allow_html=True,
                )
                if st.button(
                    f"Edit {artifact_lookup[artifact_id]['label']}",
                    key=f"podcast_artifact_pick_{run['id']}_{artifact_id}",
                    type="primary" if selected_artifact_id == artifact_id else "secondary",
                    use_container_width=True,
                ):
                    st.session_state[artifact_key] = artifact_id
                    st.rerun()

        selected_artifact = run["artifacts"][selected_artifact_id]
        artifact_text_label = f"{artifact_lookup[selected_artifact_id]['label']} Content"
        artifact_text_placeholder = "Paste the approved or draft content here."
        artifact_path_label = "Asset Path / URL"
        artifact_path_placeholder = "File path, Drive link, or external URL"
        if selected_artifact_id == "clips":
            st.info("Review the actual shorts clips here, then select the one you want to use. The notes box below is still useful for clip copy or extra context.")
            artifact_text_label = "Shorts Clip Notes"
            artifact_text_placeholder = "Paste clip notes, timecodes, or clip names here."
            artifact_path_label = "Shorts Output Folder / URL"
            artifact_path_placeholder = "Folder path, shared Drive link, ZIP URL, or clip destination"
            clip_files = _podcast_filtered_clip_files(proxy_job.get("clips_files", []), run.get("cached_clip_files", []))
            if clip_files:
                clip_lookup = {item["name"]: item for item in clip_files}
                selected_name = str(run.get("selected_clip_name", "")).strip()
                recommended_name = _podcast_recommended_clip_name(clip_files)
                preview_key = f"podcast_artifact_clip_pick_{run['id']}"
                default_name = selected_name if selected_name in clip_lookup else (recommended_name or clip_files[0]["name"])
                if preview_key not in st.session_state or st.session_state[preview_key] not in clip_lookup:
                    st.session_state[preview_key] = default_name
                preview_clip_name = st.selectbox(
                    "Pick The Clip",
                    [item["name"] for item in clip_files],
                    key=preview_key,
                    format_func=lambda clip_name: _podcast_clip_picker_label(clip_lookup[clip_name], [item["name"] for item in clip_files].index(clip_name), recommended_name),
                )
                preview_clip = clip_lookup[preview_clip_name]
                if recommended_name:
                    st.caption(f"Recommended clip: {recommended_name}")
                st.caption(f"{preview_clip['name']} · {_podcast_clip_duration_label(preview_clip.get('duration_seconds', 0.0))}")
                try:
                    preview_bytes, preview_type = _podcast_proxy_fetch_clip_bytes(run["id"], preview_clip["name"])
                    st.video(preview_bytes, format=preview_type)
                except Exception as exc:
                    st.warning(f"Could not load clip preview: {exc}")
                artifact_clip_cols = st.columns(2, gap="small")
                with artifact_clip_cols[0]:
                    select_label = "Selected" if selected_name == preview_clip["name"] else "Use This Clip"
                    if st.button(select_label, key=f"podcast_artifact_use_clip_{run['id']}", type="primary", use_container_width=True, disabled=selected_name == preview_clip["name"]):
                        updated_store = podcast_tracker.deepcopy_store(store)
                        podcast_tracker.select_clip(
                            updated_store,
                            run_id=run["id"],
                            actor=actor,
                            clip_name=preview_clip["name"],
                            clip_path=preview_clip["path"],
                        )
                        st.session_state["_podcast_flash_message"] = {"level": "success", "text": f"Selected clip: {preview_clip['name']}"}
                        _save_podcast_and_rerun(updated_store, run["id"])
                with artifact_clip_cols[1]:
                    if _podcast_run_mode(run) == "local" and _podcast_is_local_source_path(run.get("source_path", "")) and st.button("Start This Step Over", key=f"podcast_artifact_retry_clip_step_{run['id']}", use_container_width=True):
                        try:
                            clip_result = _podcast_proxy_generate_clips(run["id"], force=True)
                            if not clip_result.get("accepted", True):
                                st.warning(_podcast_user_error_text(clip_result.get("message", "Clip generation is already running.")))
                                return
                        except Exception as exc:
                            st.warning(_podcast_user_error_text(str(exc)))
                        else:
                            st.session_state["_podcast_flash_message"] = {"level": "success", "text": "Clip generation restarted."}
                            st.rerun()
            elif proxy_job.get("clips_status") in {"queued", "running"}:
                st.caption("Clips are still generating. Refresh the local runner status in Overview if you need to check again.")
            elif proxy_job.get("clips_status") == "failed":
                st.warning(proxy_job.get("clips_error", "Clip generation failed."))
        with st.form(f"podcast_artifact_form_{run['id']}_{selected_artifact_id}"):
            artifact_text = st.text_area(
                artifact_text_label,
                value=selected_artifact["text"],
                height=180,
                placeholder=artifact_text_placeholder,
            )
            artifact_path = st.text_input(
                artifact_path_label,
                value=selected_artifact["path"],
                placeholder=artifact_path_placeholder,
            )
            artifact_status = st.selectbox(
                "Artifact Status",
                list(podcast_tracker.ARTIFACT_STATUSES),
                index=list(podcast_tracker.ARTIFACT_STATUSES).index(selected_artifact["status"]),
            )
            artifact_notes = st.text_area("Artifact Notes", value=selected_artifact["notes"], height=100)
            artifact_submitted = st.form_submit_button("Save Artifact", type="primary", use_container_width=True)
        if artifact_submitted:
            updated_store = podcast_tracker.deepcopy_store(store)
            podcast_tracker.update_artifact(
                updated_store,
                run_id=run["id"],
                artifact_id=selected_artifact_id,
                actor=actor,
                text=artifact_text,
                path=artifact_path,
                status=artifact_status,
                notes=artifact_notes,
            )
            _save_podcast_and_rerun(updated_store, run["id"])

    if active_section == "Approvals":
        gate_cards = []
        gate_lookup = {gate["id"]: gate["label"] for gate in podcast_tracker.APPROVAL_GATES}
        for gate in podcast_tracker.APPROVAL_GATES:
            latest = latest_gate_decisions.get(gate["id"])
            if latest:
                value = latest["decision"].replace("_", " ").title()
                meta = f"{latest['actor'] or 'Unknown'} · {latest['created_at']}"
            else:
                value = "Pending"
                meta = "No HQ approval recorded yet."
            gate_cards.append(_podcast_card_html(gate["label"], value, meta))
        st.markdown(f'<div class="podcast-status-grid">{"".join(gate_cards)}</div>', unsafe_allow_html=True)

        with st.form(f"podcast_approval_form_{run['id']}"):
            approval_gate = st.selectbox(
                "Approval Gate",
                [gate["id"] for gate in podcast_tracker.APPROVAL_GATES],
                format_func=lambda gate_id: gate_lookup[gate_id],
            )
            approval_decision = st.selectbox(
                "Decision",
                list(podcast_tracker.APPROVAL_DECISIONS),
                format_func=lambda decision: decision.replace("_", " ").title(),
            )
            approval_advance = st.checkbox("Also advance the HQ workflow state now")
            allowed_state_after = list(podcast_tracker.ALLOWED_APPROVAL_STATE_AFTER.get(approval_gate, {}).get(approval_decision, ()))
            suggested_state_after = allowed_state_after[0] if allowed_state_after else ""
            approval_override_state = st.checkbox("Choose a different follow-up state", disabled=not (approval_advance and len(allowed_state_after) > 1))
            if approval_advance and suggested_state_after:
                st.caption(f"Suggested next state: {_PODCAST_STATE_LABELS.get(suggested_state_after, suggested_state_after)}")
            approval_state_after = suggested_state_after if approval_advance else ""
            if approval_advance and approval_override_state and allowed_state_after:
                approval_state_options = [
                    (state_id, _PODCAST_STATE_LABELS.get(state_id, state_id))
                    for state_id in allowed_state_after
                ]
                approval_state_after = st.selectbox(
                    "Advance To",
                    [item[0] for item in approval_state_options],
                    format_func=lambda value: dict(approval_state_options)[value],
                    help="Only valid follow-up states for the selected gate and decision are shown here.",
                )
            approval_notes = st.text_area("Approval Notes", height=120, placeholder="What was approved, blocked, or kicked back?")
            approval_submitted = st.form_submit_button("Record Approval", type="primary", use_container_width=True)
        if approval_submitted:
            updated_store = podcast_tracker.deepcopy_store(store)
            try:
                if approval_gate == "gate2" and approval_decision == "approved":
                    if not _podcast_artifact_has_content(run, "clips"):
                        raise ValueError("Save the reviewed clip notes before approving Gate 2.")
                    if _podcast_run_mode(run) == "local" and _podcast_is_local_source_path(run.get("source_path", "")) and not str(run.get("selected_clip_name", "")).strip():
                        raise ValueError("Pick a shorts clip before approving Gate 2 for a local HQ run.")
                podcast_tracker.record_approval(
                    updated_store,
                    run_id=run["id"],
                    gate=approval_gate,
                    decision=approval_decision,
                    actor=actor,
                    notes=approval_notes,
                    state_after=approval_state_after if approval_advance else "",
                )
            except ValueError as exc:
                st.warning(str(exc))
            else:
                _save_podcast_and_rerun(updated_store, run["id"])

        if run["approvals"]:
            approval_rows = []
            for approval in reversed(run["approvals"]):
                approval_rows.append(
                    (
                        '<div class="podcast-event-item">'
                        f'<div class="podcast-event-meta">{html.escape(approval["created_at"])} · {html.escape(approval["actor"] or "Unknown")} · {html.escape(gate_lookup[approval["gate"]])}</div>'
                        f'<div class="podcast-event-title">{html.escape(approval["decision"].replace("_", " ").title())}</div>'
                        f'<div class="podcast-event-copy">{html.escape(approval["notes"] or "No notes recorded.")}</div>'
                        '</div>'
                    )
                )
            st.markdown(f'<div class="podcast-event-log">{"".join(approval_rows)}</div>', unsafe_allow_html=True)

    if active_section == "Delivery & Verify":
        delivery_cols = st.columns(2, gap="large")
        for idx, spec in enumerate(podcast_tracker.DELIVERY_SPECS):
            delivery = run["deliveries"][spec["id"]]
            with delivery_cols[idx]:
                st.markdown('<div class="podcast-panel">', unsafe_allow_html=True)
                st.markdown(f'<div class="podcast-status-kicker">{html.escape(spec["label"])} Delivery</div>', unsafe_allow_html=True)
                with st.form(f"podcast_delivery_form_{run['id']}_{spec['id']}"):
                    delivery_status = st.selectbox(
                        "Delivery Status",
                        list(podcast_tracker.DELIVERY_STATUSES),
                        index=list(podcast_tracker.DELIVERY_STATUSES).index(delivery["status"]),
                        format_func=lambda value: value.replace("_", " ").title(),
                    )
                    delivery_id = st.text_input("External ID", value=delivery["external_id"])
                    delivery_url = st.text_input("Public URL", value=delivery["url"])
                    delivery_notes = st.text_area("Delivery Notes", value=delivery["notes"], height=100)
                    delivery_submitted = st.form_submit_button("Save Delivery", type="primary", use_container_width=True)
                st.markdown('</div>', unsafe_allow_html=True)
                if delivery_submitted:
                    updated_store = podcast_tracker.deepcopy_store(store)
                    if delivery_status in {"posted", "verified"} and not (delivery_id.strip() or delivery_url.strip()):
                        st.warning(f"Add an External ID or Public URL before marking {spec['label']} as {delivery_status.replace('_', ' ')}.")
                    else:
                        podcast_tracker.update_delivery(
                            updated_store,
                            run_id=run["id"],
                            channel=spec["id"],
                            actor=actor,
                            status=delivery_status,
                            external_id=delivery_id,
                            url=delivery_url,
                            notes=delivery_notes,
                        )
                        _save_podcast_and_rerun(updated_store, run["id"])

        verification = run["verification"]
        st.markdown('<div class="podcast-panel">', unsafe_allow_html=True)
        st.markdown('<div class="podcast-status-kicker">Verification Checklist</div>', unsafe_allow_html=True)
        with st.form(f"podcast_verification_form_{run['id']}"):
            verification_checks = {}
            verify_col1, verify_col2 = st.columns(2, gap="large")
            for idx, spec in enumerate(podcast_tracker.VERIFICATION_CHECKS):
                target_col = verify_col1 if idx % 2 == 0 else verify_col2
                with target_col:
                    verification_checks[spec["id"]] = st.checkbox(spec["label"], value=verification[spec["id"]])
            verification_notes = st.text_area("Verification Notes", value=verification["notes"], height=100)
            verification_submitted = st.form_submit_button("Save Verification", type="primary", use_container_width=True)
        st.markdown('</div>', unsafe_allow_html=True)
        if verification_submitted:
            updated_store = podcast_tracker.deepcopy_store(store)
            candidate_run = next((item for item in updated_store["runs"] if item["id"] == run["id"]), None)
            delivery_records = (candidate_run or run).get("deliveries", {})
            has_receipt = any(
                delivery.get("external_id") or delivery.get("url") or delivery.get("status") in {"posted", "verified"}
                for delivery in delivery_records.values()
            )
            if any(verification_checks.values()) and not has_receipt:
                st.warning("Record at least one posted delivery ID or public URL before checking verification boxes.")
            elif verification_checks.get("public_url_checked") and not any(delivery.get("url") for delivery in delivery_records.values()):
                st.warning("Add a public URL before marking Public URL Checked.")
            else:
                podcast_tracker.update_verification(
                    updated_store,
                    run_id=run["id"],
                    actor=actor,
                    checks=verification_checks,
                    notes=verification_notes,
                )
                _save_podcast_and_rerun(updated_store, run["id"])

    if active_section == "Activity":
        sync_col, note_col = st.columns(2, gap="large")
        with sync_col:
            with st.form(f"podcast_sync_form_{run['id']}"):
                sync_note = st.text_area(
                    "Discord Sync Note",
                    height=120,
                    value=run.get("sync_note", ""),
                    placeholder="What did you verify in Discord when syncing HQ just now?",
                )
                sync_confirmed = st.checkbox("I just checked the live Discord workflow before pressing this")
                sync_submitted = st.form_submit_button("Mark Sync Checkpoint", type="primary", use_container_width=True)
            if sync_submitted:
                if not sync_confirmed:
                    st.warning("Confirm that you just checked Discord before refreshing HQ sync time.")
                else:
                    updated_store = podcast_tracker.deepcopy_store(store)
                    podcast_tracker.record_sync_checkpoint(updated_store, run_id=run["id"], actor=actor, note=sync_note)
                    _save_podcast_and_rerun(updated_store, run["id"])
        with note_col:
            with st.form(f"podcast_manual_note_form_{run['id']}"):
                manual_note = st.text_area("Manual HQ Note", height=120, placeholder="Anything worth recording from the live Discord run.")
                note_submitted = st.form_submit_button("Add Note", type="primary", use_container_width=True)
            if note_submitted:
                updated_store = podcast_tracker.deepcopy_store(store)
                podcast_tracker.add_manual_note(updated_store, run_id=run["id"], actor=actor, note=manual_note)
                _save_podcast_and_rerun(updated_store, run["id"])

        event_rows = []
        for event in reversed(run["events"]):
            event_rows.append(
                (
                    '<div class="podcast-event-item">'
                    f'<div class="podcast-event-meta">{html.escape(event["created_at"])} · {html.escape(event["actor"] or "Unknown")} · {html.escape(event["type"].replace("_", " "))}</div>'
                    f'<div class="podcast-event-title">{html.escape(event["summary"])}</div>'
                    f'<div class="podcast-event-copy">{html.escape(event["details"] or "No extra details.")}</div>'
                    '</div>'
                )
            )
        empty_event_html = (
            '<div class="podcast-event-item">'
            '<div class="podcast-event-title">No HQ events yet.</div>'
            '<div class="podcast-event-copy">Use the forms above to start capturing the live workflow in HQ.</div>'
            '</div>'
        )
        st.markdown(
            f'<div class="podcast-event-log">{"".join(event_rows) if event_rows else empty_event_html}</div>',
            unsafe_allow_html=True,
        )
        with st.expander("Raw HQ Run JSON", expanded=False):
            st.code(json.dumps(run, indent=2), language="json")
        return

# ROUTE TO PAGES
